// Üretilen dosya: tool/ozgun/uret.py. Sanat · Resim-heykel malzemeleri, boya teknikleri, pigmentler ve sanat eseri restorasyonu (tempera, fresk, yağlıboya, guaj, astar, vernik, konservasyon ilkeleri) (orta).
const ozArt18Orta = <(String, String, List<String>, String)>[
  ('Suluboya, minyatür, el yazması ve tekstil gibi ışığa çok duyarlı organik eserler için müzelerde önerilen azami aydınlatma şiddeti sınırı kaç lükstür?', '50 lüks', ['150 lüks', '200 lüks', '300 lüks'], 'Işığa çok hassas kâğıt ve tekstil eserlerde fotokimyasal bozulmayı yavaşlatmak için aydınlatma düzeyi en fazla 50 lüks ile sınırlandırılır.'),
  ('Yağlıboya ve tempera tablolar gibi ışığa orta derecede duyarlı eserlerin sergilendiği galerilerde önerilen standart aydınlatma sınırı kaç lükstür?', '150-200 lüks', ['500-600 lüks', '750-1000 lüks', '30-40 lüks'], 'Yağlıboya tablolar orta duyarlılıktaki eserler grubuna girer ve genellikle 150 ile 200 lüks aralığında sergilenir.'),
  ('Müze aydınlatmasında ışık kaynaklarından yayılan ultraviyole (UV) radyasyon miktarı, birim lümen başına en fazla kaç mikrowatt (µW/lm) olacak şekilde filtrelenmelidir?', '75 µW/lm', ['250 µW/lm', '400 µW/lm', '600 µW/lm'], 'Uluslararası önleyici koruma standartlarına göre aydınlatma kaynaklarındaki UV oranı 75 µW/lm değerinin altına düşürülmelidir.'),
  ('Ahşap panel üzerine yapılmış bir yağlıboya tabloda bağıl nemin ani ve aşırı düşmesi durumunda aşağıdaki hasarlardan hangisi öncelikle görülür?', 'Ahşabın büzüşmesi ve boya tabakasının kabarıp dökülmesi', ['Ahşabın genleşmesi ve verniğin akışkanlaşarak damlaması', 'Metal çerçeve çivilerinin hızla paslanarak erimesi', 'Tuval bezinin küflenerek biyolojik çürümeye uğraması'], 'Bağıl nem düştüğünde higroskopik ahşap suyunu kaybederek büzüşür; esnek olmayan boya katmanı ise daralan yüzeye uyum sağlayamayıp kabarır (tenting).'),
  ('Karma koleksiyonların bulunduğu müze salonlarında genel olarak ideal kabul edilen bağıl nem aralığı aşağıdakilerden hangisidir?', '%45 - %55', ['%15 - %25', '%70 - %85', '%80 - %95'], 'Karma koleksiyonlarda hem aşırı kurumanın hem de küf oluşumunun önüne geçmek için %45-%55 bağıl nem aralığı dengeli kabul edilir.'),
  ('Karma müze galerilerinde hem eserlerin korunması hem de ziyaretçi konforu gözetilerek belirlenen standart sıcaklık aralığı kaç santigrat derecedir?', '18 - 22 °C', ['5 - 10 °C', '26 - 32 °C', '30 - 35 °C'], 'Kimyasal bozulma hızını düşük tutarken insan konforunu da sağlayan müze sıcaklığı standardı genellikle 18-22 °C aralığıdır.'),
  ('Akkor telli ve halojen lambaların sanat eserlerine doğrudan ve yakından tutulması, UV dışında özellikle hangi radyasyon nedeniyle yüzeysel ısınma ve kurumaya yol açar?', 'Kızılötesi (IR) radyasyon', ['Gama radyasyonu', 'X-ışını radyasyonu', 'Alfa parçacık ışıması'], 'Akkor ve halojen kaynaklar yüksek oranda kızılötesi (infrared) ışın yayarak eser yüzeyinin sıcaklığını artırır ve lokal bağıl nemi düşürür.'),
  ('Müze vitrinlerinin yapımında meşe gibi taze ahşap veya uygun olmayan MDF panellerin kullanılması sonucunda uçucu organik asitlerin (formik ve asetik asit) kurşun veya kalkerli eserlerde korozyon yaratması hangi testle önceden saptanır?', 'Oddy testi', ['Karbon-14 testi', 'Termolüminesans testi', 'İyot nişasta testi'], 'Oddy testi, vitrin ve depolama malzemelerinin kapalı ortamda metaller (gümüş, kurşun, bakır) üzerinde korozyona yol açacak gaz salımı yapıp yapmadığını ölçen hızlandırılmış yaşlandırma testidir.'),
  ('Müzelerde kimyasal ilaçlama (fümigasyon) yerine tuzaklar, karantina, temizlik ve çevresel kontrol ile böcek ve kemirgenlerin engellenmesi yaklaşımına ne ad verilir?', 'Entegre zararlı yönetimi', ['Reaktif kimyasal sterilizasyon', 'Biyolojik radyasyon arıtımı', 'Termal şok dezenfeksiyonu'], 'Entegre zararlı yönetimi (Integrated Pest Management - IPM), toksik kimyasallara başvurmadan izleme ve önleme yoluyla biyolojik zararlıları kontrol eder.'),
  ('Doğal reçine verniklerinin zamanla sararmasının ve kahverengileşmesinin temel kimyasal nedeni aşağıdakilerden hangisidir?', 'Işık ve oksijen etkisiyle gerçekleşen otooksidasyon ve çapraz bağlanma', ['Ortam neminin reçine içindeki silisyum atomlarını kristalleştirmesi', 'Tuval bezindeki selüloz liflerinin boya yüzeyine doğru göç etmesi', 'Kalsiyum karbonat astarın reçine tabakasını bazikleştirerek yakması'], 'Doğal triterpenoid reçineler (dammar, mastik) zamanla oksidasyona uğrar; doymamış çift bağlar ve keton grupları oluşarak mavi ışığı soğurur ve sarı-kahverengi görünüm yaratır.'),
  ('Sararmış kalın bir vernik tabakası, altındaki yağlıboya resmin görsel algısını özellikle hangi renk tonlarında en ağır biçimde bozar?', 'Mavi tonları yeşilimsiye çevirir ve beyaz ışıklı alanları sıcak-koyu gösterir', ['Kırmızı tonları parlak mora dönüştürür ve siyah gölgeleri tamamen beyaza açar', 'Sarı pigmentleri koyu laciverte çevirir ve yeşil alanları grileştirir', 'Kahverengi zeminleri turkuaz rengine yaklaştırır ve kontrastı aşırı yükseltir'], 'Sararmış vernik sarı-turuncu bir filtre gibi davranarak kısa dalga boylu mavi ışığı soğurur; bu yüzden gökyüzü mavileri yeşile çalar, soğuk beyazlar kirli sarı görünür.'),
  ('Restoratörlerin vernik inceltme veya temizleme işleminden önce resmin kenarında küçük ve göze çarpmayan noktalarda uygun çözücü karışımını belirlemek için yaptıkları ön denemeye ne ad verilir?', 'Çözünürlük testi', ['Mikro-sertlik penetrasyon deneyi', 'Termogravimetrik kül analizi', 'Radyokarbon yaşlandırma deneyi'], 'Temizlik öncesinde boya katmanına zarar vermeden yalnızca verniği çözen en düşük polariteli çözücü karışımını bulmak için lokal çözünürlük testleri uygulanır.'),
  ('Vernik temizliği sırasında restoratörün tabloyu karanlık odada ultraviyole (UV) lamba altında incelemesinin temel amacı nedir?', 'Eski doğal reçine verniğinin yeşilimsi-sarı floresansından yararlanarak vernik kalıntılarını ve önceki rötuşları görmek', ['Tuvalin arka yüzündeki ahşap şasinin nem oranını kızılötesi yansımayla hesaplamak', 'Boya tabakasının altındaki kurşun kalem ön çizimlerini yüzeye çıkarmak', 'Çözücü buharlarının solunum havasındaki yoğunluğunu optik olarak ölçmek'], 'Yaşlanmış doğal reçine vernikleri UV ışık altında karakteristik sarı-yeşil floresans verirken, yeni rötuşlar koyu/mor leke olarak görünür; böylece temizliğin homojenliği kontrol edilir.'),
  ('Vernik tabakasının yüksek nem veya uygunsuz çözücü teması sonucunda mikroskobik boşluklar oluşturup ışığı dağıtarak mavimsi-beyaz bulanık bir görünüm almasına ne ad verilir?', 'Beyazlama / buğulanma', ['Kraklür ağlaşması', 'Bronz hastalığı', 'Sabunlaşma krateri'], 'Vernik içinde mikro çatlaklar veya nem kaynaklı boşluklar oluştuğunda ışık saçılıma uğrar ve koyu boya alanları üzerinde dumanlı beyaz-mavimsi bir pus (blooming) belirir.'),
  ('Hassas boya yüzeylerinde çözücünün alt katmanlara hızla sızmasını engellemek ve yalnızca en üstteki vernik yüzeyinde kontrollü etki etmesini sağlamak için restoratörler çözücüyü hangi formda uygular?', 'Çözücü jeller veya emülsiyonlar halinde', ['Yüksek basınçlı sıcak buhar püskürtmesiyle', 'Asidik sulu daldırma banyosu içinde', 'Aşındırıcı zımpara tozuyla karıştırarak'], 'Richard Wolbers gibi uzmanların geliştirdiği çözücü jeller, yüksek viskoziteleri sayesinde kılcal emilimi sınırlar ve temizliği yalnızca yüzeyle kısıtlar.'),
  ('Bir yağlıboya tabloda boya henüz kurumakta iken ortaya çıkan, yuvarlak kenarlı, geniş aralıklı ve alttaki astar veya alt boya katmanına kadar inmeyen çatlak türü hangisidir?', 'Kuruma çatlağı (erken kraklür)', ['Yaşlanma çatlağı (mekanik kraklür)', 'Şasi darbe halkası çatlağı', 'Donma-çözülme kırığı'], 'Kuruma çatlakları (drying cracks), boya filminin kururken büzüşmesi veya hızlı kuruyan boyanın yavaş kuruyan yağlı alt katman üzerine sürülmesiyle erken dönemde oluşur ve kenarları yuvarlaktır.'),
  ('Boya ve astar katmanlarının on yıllar içinde gevrekleşmesi ve tuval/ahşap desteğin hareketlerine uyum sağlayamaması sonucu oluşan, keskin kenarlı ve astar boyunca desteğe kadar inen çatlak türü hangisidir?', 'Yaşlanma çatlağı', ['Fırça izi kabartması', 'Vernik akıntısı damlası', 'Bitüm erime lekesi'], 'Yaşlanma çatlakları (age cracks), zamanla elastikiyetini yitirip kırılganlaşan boya ve astar katmanlarının mekanik gerilimlerle keskin hatlar halinde kırılmasıyla meydana gelir.'),
  ('18. ve 19. yüzyıl akademik resminde koyu gölgeler elde etmek için kullanılan, ancak tam anlamıyla kuruyup polimerleşmediği için büzüşme, kararma ve derin adacıklı çatlaklar yaratan malzeme hangisidir?', 'Bitüm (asfalt / mumya kahverengisi)', ['Lapis lazuli (doğal ultramarin)', 'Sarı aşıboyası (demir oksit)', 'Terre verte (yeşil toprak)'], 'Bitüm veya asfalt bazlı kahverengiler kuruyan bir yağ filmi oluşturmaz; sıcaklık ve zamanla akışkanlaşıp büzüşerek geri döndürülemez derin kraklür adacıkları yaratır.'),
  ('Kraklür adacıklarının kenarlarının yukarı doğru kıvrılarak çanak benzeri içbükey bir biçim almasına konservasyonda ne ad verilir?', 'Çanaklaşma (cupping)', ['Tozlaşma (chalking)', 'Akma (sagging)', 'Çiçeklenme (efflorescence)'], 'Kraklür adacıklarının kenarları zamanla gerilim ve nem değişimleriyle yukarı kalkar; bu içbükey deformasyona çanaklaşma (cupping) denir.'),
  ('Kraklür boyunca destekten ayrılıp kabaran ve dökülme tehlikesi gösteren boya pullarını yeniden alt katmana yapıştırmak için yapılan işleme ne ad verilir?', 'Boya katmanı sağlamlaştırma', ['Yüzeysel vernik inceltme', 'Kromatik soyutlama', 'Fotogrametrik belgeleme'], 'Kabaran ve ayrılan (flaking/cleavage) boya katmanlarının çatlak aralarından uygun bir yapıştırıcı (ör. mersin balığı tutkalı, Beva 371, Aquazol) verilerek sabitlenmesine konsolidasyon denir.'),
  ('Modern restorasyon kuramının temellerini atan ve 1963\'te yayımladığı "Restorasyon Teorisi" (Teoria del Restauro) adlı eseriyle koruma etiğine yön veren İtalyan kuramcı kimdir?', 'Cesare Brandi', ['Eugène Viollet-le-Duc', 'Giorgio Vasari', 'Johann Joachim Winckelmann'], 'Roma Merkez Restorasyon Enstitüsü\'nün (ICR) kurucu müdürü Cesare Brandi, estetik ve tarihsel değer dengesini kurarak çağdaş koruma etiğinin kuramsal çerçevesini çizmiştir.'),
  ('Cesare Brandi\'nin restorasyon kuramına göre, bir sanat eserine müdahale edilirken uzlaştırılması gereken iki temel boyut (ikilik) aşağıdakilerden hangisidir?', 'Estetik boyut ve tarihsel boyut', ['Ticari boyut ve politik boyut', 'Dinsel boyut ve mitolojik boyut', 'Mekanik boyut ve akustik boyut'], 'Brandi\'ye göre sanat eseri hem sanatsal niteliğiyle estetik bir varlık hem de üretildiği ve yaşadığı dönemlerin izini taşıyan tarihsel bir belgedir; restorasyon ikisini de gözetmelidir.'),
  ('19. yüzyılda Eugène Viollet-le-Duc\'ün savunduğu ve yapıyı "belki de hiç var olmamış eksiksiz bir üslup bütünlüğüne kavuşturmayı" hedefleyen yaklaşım, modern koruma etiğinde neden reddedilir?', 'Varsayıma dayalı eklemelerle tarihsel özgünlüğü bozduğu ve sahte bir geçmiş yarattığı için', ['Yapılarda yalnızca kireç harcı yerine çimento kullanılmasını yasakladığı için', 'Sanat eserlerinin müzelerde sergilenmesine tamamen karşı çıktığı için', 'Yalnızca antik Yunan heykellerinin korunmasına izin verdiği için'], 'Üslup birliği (stylistic restoration) yaklaşımı, sonradan eklenen tarihsel katmanları yok edip hayali tamamlamalar yaptığı için belgesel doğruluğu zedeler.'),
  ('19. yüzyıl düşünürü John Ruskin\'in Viollet-le-Duc\'e karşı çıkarak restorasyonu "bir binanın uğrayabileceği en bütünsel yıkım" olarak nitelendirmesi hangi yaklaşıma temel oluşturmuştur?', 'Koruma / muhafaza (anti-restorasyon) hareketine', ['Barok yeniden bezeme akımına', 'Endüstriyel kopyalama ekolüne', 'Fütüristik yıkım manifestosuna'], 'John Ruskin ve William Morris, yapıların yaşlanma izlerine dokunulmaması ve yalnızca düzenli bakımla ayakta tutulması gerektiğini savunarak modern önleyici koruma bilincini beslemiştir.'),
  ('Yağlıboya bir tablonun eksik kısımlarını tamamlarken (rötuş yaparken) restoratörün yağlıboya yerine suluboya, guaj veya sentetik reçine boyaları (ör. Paraloid B-72, Gamblin) tercih etmesinin etik nedeni nedir?', 'Rötuşun özgün yağlıboya katmanına zarar vermeyen hafif çözücülerle kolayca geri silinebilmesini sağlamak', ['Yağlıboyanın tuval üzerinde hiçbir zaman kurumayıp sürekli akışkan kalmasını önlemek', 'Suluboyanın güneş ışığı altında yağlıboyadan on kat daha parlak görünmesini sağlamak', 'Orijinal boyanın kimyasal yapısını değiştirerek onu suya dayanıklı hale getirmek'], 'Yağlıboya zamanla çapraz bağlanıp çözünmezleştiği için rötuşta kullanılmaz; bunun yerine özgün boyayı etkilemeyen çözücülerle kolayca çıkarılabilen geri döndürülebilir bağlayıcılar kullanılır.'),
  ('Tarihi anıtların ve kültür varlıklarının korunması ve restorasyonu konusunda uluslararası temel ilkeleri belirleyen ve "restorasyon uzmanlık gerektiren istisnai bir işlemdir, varsayımın başladığı yerde durmalıdır" diyen 1964 tarihli belge hangisidir?', 'Venedik Tüzüğü', ['Kyoto Protokolü', 'Maastricht Antlaşması', 'Cenevre Sözleşmesi'], '1964 tarihli Venedik Tüzüğü, özgün malzemeye saygı, dönem eklerinin korunması, varsayımdan kaçınma ve tamamlamaların ayırt edilebilir olması ilkelerini evrenselleştirmiştir.'),
  ('Sanat eserinin zaman içinde edindiği, bozulma oluşturmayan doğal yaşlanma izleri ve yüzey olgunlaşmasına koruma kuramında ne ad verilir?', 'Patina', ['Laküna', 'Pentimento', 'Korozyon kabuğu'], 'Patina, malzemenin zamanla kazandığı ve eserin tarihselliğini yansıtan doğal yüzey eskimesidir; Brandi\'ye göre patina silinmemeli ve korunmalıdır.'),
  ('Bir tablo, fresk veya mozaik yüzeyinde boya ya da malzeme tabakasının dökülmesi sonucu ortaya çıkan boşluk ve kayıp alanlara konservasyon dilinde ne ad verilir?', 'Laküna (lacuna)', ['İmpasto', 'Grisaille', 'Karton (cartoon)'], 'Latince boşluk anlamına gelen laküna, görsel bütünlüğü kesintiye uğratan boya veya sıva kaybı bölgelerini ifade eder.'),
  ('Bir yağlıboya tablodaki kayıp alana (lakünaya) renkli rötuş yapılmadan önce, özgün boya ile yeni dolgu ve rötuş katmanı arasına ince bir koruyucu vernik sürülmesinin amacı nedir?', 'Özgün katman ile yeni müdahaleyi fiziksel olarak ayırmak (izolasyon verniği) ve ileride rötuşun kolayca silinmesini sağlamak', ['Alttaki ahşap panelin oksijenle temasını tamamen keserek fosilleşmesini başlatmak', 'Yeni sürülecek suluboya rötuşun tuvalin arka yüzüne geçmesini hızlandırmak', 'Özgün boyadaki kurşun beyazı pigmentini kimyasal olarak sarartmak'], 'İzolasyon verniği, orijinal eser yüzeyi ile restorasyon malzemeleri arasında güvenli bir sınır (bariyer) oluşturur ve geri döndürülebilirliği garanti altına alır.'),
  ('Yıpranmış ve kenarları çürümüş bir tuval tablonun arkasına yeni bir destek tuvali yapıştırılması (astarlama / relining) işlemi, modern koruma etiğinde neden artık rutin olmaktan çıkarılıp son çare olarak görülmektedir?', 'Isı, basınç ve yoğun yapıştırıcı kullanımıyla eserin özgün doku karakterini düzleştirip geri dönüşü zor bir müdahale oluşturduğu için', ['Yeni tuval bezinin her zaman ön yüzdeki renkleri morötesi ışığa karşı daha dayanıksız kıldığı için', 'Astarlama yapılan tabloların çerçeveye takılmasının fiziksel olarak olanaksız hale gelmesi yüzünden', 'Keten liflerinin boyadaki mavi pigmentleri mıknatıs gibi arka yüze çekmesi sebebiyle'], 'Tam astarlama (lining) ağır bir yapısal müdahaledir; en az müdahale ilkesi gereği günümüzde mümkünse yalnızca yırtık onarımı veya kenar şerit takviyesi (strip-lining) tercih edilir.'),
  ('Avrupa Konservatör-Restoratör Kuruluşları Konfederasyonu\'nun kısaltması olan ve koruma meslek etiği ilkelerini standartlaştıran uluslararası çatı kuruluşu hangisidir?', 'E.C.C.O.', ['F.I.F.A.', 'C.E.R.N.', 'O.P.E.C.'], 'E.C.C.O. (European Confederation of Conservator-Restorers\' Organisations), mesleki yeterlilik ve koruma etiği rehberlerini yayımlayan temel Avrupa kuruluşudur.'),
  ('Uluslararası Müzeler Konseyi (ICOM) bünyesinde faaliyet gösteren ve kültür varlıklarının korunması alanındaki en geniş uluslararası uzmanlık komitesi hangisidir?', 'ICOM-CC', ['ICOMOS-ICAHM', 'UNESCO-MAB', 'ICCROM-ATHAR'], 'ICOM-CC (Committee for Conservation), müze konservasyonu alanındaki çalışma gruplarını bir araya getiren küresel bilimsel komitedir.'),
  ('Sanat eserlerinin müzeler arası ödünç sergiler için taşınması sırasında sıcaklık, bağıl nem ve sarsıntı şoklarından korunması amacıyla nasıl bir paketleme yapılır?', 'Isı yalıtımlı, sarsıntı emici köpüklü ve nem tamponlayıcı (ör. şartlandırılmış silika jel içeren) iklim kasaları kullanılır', ['Hava sirkülasyonunu artırmak için üstü tamamen açık tel kafes sepetler tercih edilir', 'Eserler doğrudan ıslak gazete kâğıtlarına sarılarak ahşap sandıklara sıkıştırılır', 'Kasa içine nemi artırmak amacıyla açık kaplarda kaynar su yerleştirilir'], 'Taşıma kasaları dış ortam dalgalanmalarını sönümleyen mikro-iklim kutuları gibi tasarlanır; darbe emici polietilen köpükler ve şartlandırılmış silika jel ile iç denge korunur.'),
  ('Çerçeveli bir tablonun ön yüzünde koruyucu müze camı ve arka yüzünde sızdırmaz arka kapama levhası (backing board) bulunmasının önleyici korumadaki en önemli işlevi nedir?', 'Toz ve kir girişini kesmek, arkadan gelebilecek darbeleri önlemek ve hızlı nem-sıcaklık dalgalanmalarını tamponlamak', ['Tablonun ağırlığını artırarak duvardaki askı kancalarının daha sıkı gerilmesini sağlamak', 'Boya katmanının oksijenle temasını artırarak yağların daha çabuk sararmasına yardımcı olmak', 'UV ışınlarını çerçeve içine hapsederek renklerin daha sıcak görünmesini sağlamak'], 'Arka kapama levhası (backing board) ve cam, çerçeve içinde kapalı bir mikro-iklim oluşturarak ortamdaki ani nem değişimlerini yavaşlatır ve mekanik/toz koruması sağlar.'),
  ('Büyük boyutlu, yırtılma riski taşıyan ince kâğıt eserler veya kırılgan tekstiller taşınırken neden kalın pamuklu eldiven yerine temiz nitril eldiven veya özel destek kartonları tercih edilir?', 'Kalın pamuklu eldivenler dokunma hassasiyetini azaltıp lifleri kırılgan kenarlara takılabildiği için', ['Pamuk lifleri kâğıtla temas ettiğinde anında tutuşma tehlikesi yarattığı için', 'Pamuklu eldivenler müze ışıklarında ultraviyole radyasyon ürettiği için', 'Nitril eldivenler kâğıttaki asidi kendiliğinden emip nötralize ettiği için'], 'Kalın bez eldivenler parmak uçlarındaki hissi köreltir ve pürüzlü dokusuyla kalkık boya ya da yırtık kâğıt kenarlarına takılabilir; bu yüzden pudrasız nitril eldiven kullanılır.'),
  ('Modern LED aydınlatmaların müze konservasyonunda geleneksel halojen ve floresan lambalara göre tercih edilmesinin en önemli iki teknik üstünlüğü nedir?', 'Neredeyse hiç UV ve kızılötesi (ısı) radyasyon yaymamaları', ['Eser yüzeyindeki sararmış vernikleri ışınla kendiliğinden beyazlatmaları', 'Bağıl nemi otomatik olarak %50 seviyesine yükseltmeleri', 'Mavi dalga boyunu hiç üretmeden yalnızca morötesi ışık vermeleri'], 'Kaliteli müze LED\'leri spektrumlarında UV ve IR barındırmadıkları için hem fotokimyasal UV hasarını hem de yüzey ısınmasını en aza indirir.'),
  ('Tratteggio (rigatino) tamamlama tekniği 1940\'ların ikinci yarısında Roma\'da Cesare Brandi yönetimindeki hangi uzman çift tarafından uygulamaya konulup geliştirilmiştir?', 'Paolo ve Laura Mora', ['Robert ve Sonia Delaunay', 'Charles ve Ray Eames', 'Christo ve Jeanne-Claude'], 'Restoratörler Paolo Mora ve Laura Mora, Cesare Brandi\'nin kuramsal ilkeleri doğrultusunda Roma Merkez Restorasyon Enstitüsü\'nde tratteggio tekniğini sistemleştirmiştir.'),
  ('Tratteggio tekniğinde kayıp alandaki istenen renk tonu nasıl elde edilir?', 'Saf renklerin palet üzerinde karıştırılmadan, ince dikey çizgiler halinde yan yana ve üst üste şeffafça uygulanmasıyla gözde optik olarak kaynaşmasıyla', ['Bütün pigmentlerin kalın bir spatula yardımıyla macun halinde homojen biçimde sıvanmasıyla', 'Kayıp alanın üzerine orijinal resmin yüksek çözünürlüklü fotoğraf çıktısının yapıştırılmasıyla', 'Siyah ve beyaz yağlıboyanın kalın fırça darbeleriyle dairesel olarak sürülmesiyle'], 'Divizyonizm/puantilizm prensibine benzer biçimde saf suluboya çizgileri yan yana dizilir; normal izleme mesafesinden insan gözü bu çizgileri optik karışımla bütünsel ton olarak algılar.'),
  ('Tamamlama tekniklerinden "puntinato" (noktalama) yönteminde laküna yüzeyi nasıl bütünlenir?', 'Çok ince fırça ucuyla yan yana konulan küçük renk noktalarının yoğunluğu ayarlanarak', ['Metal bir tarakla ıslak alçı yüzeyine derin yatay oluklar açılarak', 'Boya tabancasıyla geniş alana akrilik sprey boya püskürtülerek', 'Yüzeye renkli cam boncuklar yapıştırılarak'], 'Puntinato (noktalama) tekniğinde çizgi yerine mikro noktalar kullanılır; özellikle minyatür, kâğıt eser, fotoğraf veya pürüzlü dokulu yüzeylerde yumuşak geçiş ve ayırt edilebilirlik sağlar.'),
  ('Büyük kayıplarda figürü çizgisel olarak tamamlamak yerine kayıp alanı çevredeki baskın alt tona uyumlu tekdüze ve sakin bir suluboya yıkamasıyla geriye çekme yöntemine ne ad verilir?', 'Acqua sporca (nötr tonlama / kirli su tekniği)', ['Trompe-l\'oeil (göz yanıltması)', 'Alla prima (doğrudan boyama)', 'Impasto (kalın boya yığma)'], 'İtalyancada "kirli su" anlamına gelen acqua sporca, özellikle duvar resimlerinde (fresklerde) tamamlanamayacak lakünaları hafif suluboya tonlamasıyla görsel olarak sakinleştirmek için kullanılır.'),
  ('Ticari sanat piyasasında bazen tercih edilen "tam görünmez / illüzyonist (mimetik) rötuş" ile müze konservasyonundaki "tratteggio" arasındaki temel etik fark nedir?', 'Mimetik rötuş çıplak gözle tamamıyla gizlenmeyi amaçlarken, tratteggio yakından çıplak gözle ayırt edilebilir olmayı ilke edinir', ['Mimetik rötuş yalnızca kurşun kalemle yapılırken, tratteggio yalnızca yağlıboyayla yapılır', 'Mimetik rötuş eserin değerini sıfırlarken, tratteggio orijinal boyayı tamamen kazımayı gerektirir', 'Mimetik rötuş UV ışıkta hiç görünmezken, tratteggio yalnızca karanlıkta görülebilir'], 'Müzecilik ve bilimsel korumada tratteggio izleyiciyi yanıltmadan bütünlük kurar; mimetik rötuş ise çıplak gözle ayırt edilemez, ancak UV ışık ve mikroskop altında saptanabilir.'),
  ('Bir tablodaki lakünaya tratteggio uygulanmadan önce kayıp çukurunun özgün boya seviyesine getirilmesi için genellikle hangi geleneksel dolgu malzemesi kullanılır ve yüzeyi nasıl hazırlanır?', 'Hayvansal tutkal ve kalsiyum karbonat/kalsiyum sülfat karışımı (gesso) uygulanıp pürüzsüz beyaz bir zemin oluşturulur', ['Gri çimento ve kalın dere kumu karıştırılıp pürüzlü ve koyu siyah bir yüzey bırakılır', 'Saf balmumu ve motor yağı karıştırılarak kaygan ve su itici bir tabaka sürülür', 'Paslı demir talaşı ve epoksi reçine dökülerek mıknatıslı bir dolgu yapılır'], 'Tratteggio suluboyalarının berrak ve ışıklı görünebilmesi için laküna, geleneksel tutkal-tebeşir/alçı (gesso) dolgusuyla doldurulup beyaz ve düzgün bir zemin haline getirilir.'),
  ('15. ve 17. yüzyıllarda keten ve pamuk paçavralarından üretilen el yapımı kâğıtların, 19. yüzyıl sonundaki gazete ve kitap kâğıtlarından çok daha sağlam kalmasının temel nedeni nedir?', 'Paçavra kâğıtlarının uzun ve saf selüloz liflerinden oluşması, odun hamuru kâğıtlarının ise lignin ve asidik şap-reçine içermesi', ['Eski kâğıtların tamamının kurşun levhalarla kaplanarak üretilmiş olması', '19. yüzyıl kâğıtlarında bağlayıcı olarak yalnızca yumurta akı kullanılması', 'Matbaa mürekkebinin 15. yüzyılda tamamen bazik kalsiyumdan yapılması'], '1840\'lardan sonra yaygınlaşan mekanik odun hamuru yüksek oranda lignin içerir ve şap-kolofonyum (alum-rosin) haşıllamasıyla birleştiğinde güçlü içsel asitlik üretir.'),
  ('Odun hamuru kâğıtlarında bulunan hangi doğal polimer, ışık ve oksijenle temas ettiğinde hızla oksitlenerek hem koyu sarı-kahverengi renk değişimine hem de karboksilik asit oluşumuna yol açar?', 'Lignin', ['Kitin', 'Keratin', 'Kollajen'], 'Ağaç dokusunda hücreleri bir arada tutan lignin, fotokimyasal olarak çok kararsızdır; kâğıt hamurundan uzaklaştırılmazsa hızla sararma ve asitlenme yapar.'),
  ('Suya dayanıklı mürekkep içeren tek yapraklı tarihi belgelerin sulu (aköz) yöntemle asitsizleştirilmesinde en sık kullanılan bileşikler hangileridir?', 'Kalsiyum hidroksit veya kalsiyum bikarbonat / magnezyum bikarbonat çözeltileri', ['Sülfürik asit ve nitrik asit karışımları', 'Sodyum hipoklorit (çamaşır suyu) ve tuz ruhu', 'Aseton içinde çözülmüş epoksi reçinesi'], 'Sulu banyolarda kalsiyum bikarbonat, kalsiyum hidroksit veya magnezyum bikarbonat kullanılır; bunlar kuruduğunda lif aralarında zararsız kalsiyum/magnezyum karbonat tamponu oluşturur.'),
  ('Yırtılmış veya kırılganlaşmış tarihi kâğıtların onarımında uzun lifli, asitsiz, ince ve çok dayanıklı olduğu için tüm dünyada standart olarak kullanılan geleneksel el yapımı kâğıt hangisidir?', 'Japon kâğıdı', ['Karbon kopya kâğıdı', 'Parafinli kasap kâğıdı', 'Zımpara kâğıdı'], 'Dut ağacı (kozo) gibi bitkilerin uzun iç kabuk liflerinden üretilen Japon kâğıtları, ince gramajlarına rağmen yüksek çekme direncine ve kimyasal saflığa sahiptir.'),
  ('Kâğıt konservasyonunda Japon kâğıdı yamalarını yapıştırmak için geri döndürülebilirliği ve yaşlanma direnci nedeniyle en çok tercih edilen geleneksel yapıştırıcı hangisidir?', 'Saf buğday nişastası kolası (veya metil selüloz)', ['Siyanoakrilat (japon yapıştırıcısı)', 'Sıcak silikon tabancası mumu', 'Kontak kauçuk yapıştırıcısı'], 'Arıtılmış buğday nişastası muhallebisi ve selüloz eterleri (metil selüloz, Klucel G) asitsizdir, zamanla sararmaz ve nemlendirilerek kolayca geri alınabilir.'),
  ('Eski kâğıt, gravür ve kitap sayfalarında dağınık, küçük pas rengi veya sarımsı-kahverengi benekler halinde beliren lekelenme türüne konservasyon literatüründe ne ad verilir?', 'Tilki lekesi', ['Kraklür', 'Pentimento', 'Blanching'], 'Foxing (tilki tüyü rengine benzetildiği için), kâğıttaki iz metal (demir/bakır) safsızlıkları ve yüksek nemde gelişen mantar/küf metabolitlerinin etkileşimiyle oluşan kahverengi beneklerdir.'),
  ('Kâğıdın yüzeyine zarar vermeden pH değerini ölçmek isteyen bir konservatör hangi elektrot tipine sahip pH metreyi kullanır?', 'Düz uçlu (yüzey temaslı) cam elektrot', ['Toprak burgulu sivri metal prob', 'Yüksek sıcaklıklı eriyik daldırma probu', 'Gaz basıncı manometresi'], 'Tek damla saf su aracılığıyla kâğıt yüzeyinden tahribatsız ölçüm alabilmek için düz diyaframlı yüzey pH elektrodu kullanılır.'),
  ('Bir tablonun incelenmesinde kullanılan pigmentin kimyasal sentez veya keşif tarihinin, tablonun iddia edilen yapım tarihinden daha geç olması (anakronizm) sahtecilik tespitinde ne ifade eder?', 'Eserin (veya o boya katmanının) pigmentin icat edildiği tarihten önce yapılmış olamayacağını kesin olarak kanıtlar', ['Ressamın geleceği görerek o pigmenti doğada tesadüfen bulduğunu gösterir', 'Tablonun kesinlikle orijinal olduğunu ancak müzede kirlenerek renk değiştirdiğini kanıtlar', 'Tarihlendirme açısından hiçbir bilimsel değer taşımadığını gösterir'], 'Pigment kronolojisi sahtecilik tespitinin en güçlü silahlarından biridir; örneğin 17. yüzyıl iddiası taşıyan bir resmin özgün katmanında 20. yüzyıl pigmenti çıkması anakronizmdir.'),
  ('1920\'li yılların başında ticari olarak üretilmeye başlanan ve sözde Rönesans veya 18.-19. yüzyıl tablolarında saptandığında eserin modern bir sahtecilik olduğunu ele veren beyaz pigment hangisidir?', 'Titanyum beyazı (titanyum dioksit)', ['Kurşun beyazı (üstübeç)', 'Kireç beyazı (Bianco di San Giovanni)', 'Kemik beyazı (kalsiyum fosfat)'], 'Titanyum dioksit (anataz ~1920, rutil ~1938-1941) modern bir pigmenttir; önceki yüzyıllarda yağlıboyada temel beyaz pigment kurşun beyazıydı (19. yüzyılda çinko beyazı eklendi).'),
  ('1704-1706 yıllarında Berlin\'de Diesbach tarafından tesadüfen sentezlenen ilk modern sentetik pigment olan ve 17. yüzyıl veya öncesi tablolarda bulunması sahtecilik ya da geç rötuş kanıtı sayılan mavi pigment hangisidir?', 'Prusya mavisi (ferrik ferrosiyanür)', ['Doğal ultramarin (lapis lazuli)', 'Mısır mavisi (kalsiyum bakır silikat)', 'Azurit (bazik bakır karbonat)'], 'Prusya mavisi 18. yüzyıl başında sentezlenmiştir; daha erken dönem iddiasındaki eserlerde (ör. sahte Vermeer veya Ortaçağ ikonalarında) çıkması kesin tarih sınırı verir.'),
  ('Bir tablonun boya katmanının altındaki kurşun kalem veya kömür ön çizimlerini (alt çizim / underdrawing) esere hiç dokunmadan görüntülemek için kullanılan görüntüleme yöntemi hangisidir?', 'Kızılötesi reflektografi', ['Ultraviyole floresans fotoğrafçılığı', 'Taramalı elektron mikroskobu', 'Atomik absorpsiyon spektroskopisi'], 'Yakın kızılötesi ışınlar (900-1700 nm) üstteki pek çok boya katmanından geçer, beyaz astardan yansır ancak karbon bazlı siyah alt çizimler tarafından soğurularak gizli taslağı görünür kılar.'),
  ('20. yüzyılın en ünlü sanat sahtecilerinden biri olan ve kurumasını hızlandırmak için boyasına bakalit (fenol-formaldehit reçinesi) karıştırarak yaptığı sahte Johannes Vermeer tablolarıyla tanınan Hollandalı ressam kimdir?', 'Han van Meegeren', ['Elmyr de Hory', 'Wolfgang Beltracchi', 'Eric Hebborn'], 'Han van Meegeren, 1930\'lar ve 1940\'larda yağlıboyayı fırınlayıp bakalit reçinesiyle sertleştirerek çözücü testlerini yanıltan sahte Vermeer tabloları üretmiş, sonradan piroliz-GC/MS gibi analizlerle bakalit kesin olarak kanıtlanmıştır.'),
  ('Arkeolojik pişmiş toprak (terrakota) heykelciklerin ve seramiklerin sahte olup olmadığını anlamak için malzemenin en son yüksek ısıda fırınlandığı tarihi kristal kafeste biriken radyasyon enerjisini ölçerek saptayan yöntem hangisidir?', 'Termolüminesans (TL) tarihlendirmesi', ['Dendrokronoloji halka sayımı', 'Asit-baz titrasyon analizi', 'Teas çözünürlük üçgeni testi'], 'Kuvars ve feldspat kristalleri pişirme sırasında sıfırlanır ve zamanla çevresel radyasyonla elektron biriktirir; örnek yeniden ısıtıldığında yaydığı ışık (termolüminesans) son pişirilme yaşını verir ve sahte antik seramikleri anında yakalar.'),
  ('Sanat eserinden hiçbir numune almadan (tahribatsız olarak) noktasal element analizi yaparak pigmentlerdeki kurşun, cıva, kobalt, titanyum, çinko veya bakır varlığını belirleyen taşınabilir cihaz tekniği hangisidir?', 'X-ışını floresans spektroskopisi (XRF)', ['Gaz kromatografisi - kütle spektrometrisi (GC-MS)', 'Yüksek performanslı sıvı kromatografisi (HPLC)', 'Diferansiyel taramalı kalorimetri (DSC)'], 'Taşınabilir XRF (veya taramalı MA-XRF), esere temas etmeden elementel bileşimi saniyeler içinde vererek inorganik pigmentlerin haritalanmasını sağlar.'),
  ('Bir tablonun katman dizilimini (astar, alt çizim, ara boya katmanları, eski vernik, üst rötuş) mikroskop altında doğrudan görmek için var olan bir çatlak veya kenardan iğne ucu küçüklüğünde alınan örneğin şeffaf reçine içine gömülüp parlatılmasıyla hazırlanan kesite ne denir?', 'Boya kesiti', ['Karbon kopya kalıbı', 'Alçı rölyef dökümü', 'Paspartu penceresi'], 'Stratigrafik boya kesiti (cross-section), katmanların sırasını inceleyerek bir katmanın özgün mü yoksa eski vernik üzerine atılmış sonradan bir ekleme mi olduğunu kesinleştirir.'),
  ('Tablo yüzeyine çok dar bir açıyla (yüzeye neredeyse paralel, 5°-15°) ışık tutularak boya kabartılarının (impasto), kraklür kalkmalarının ve tuval deformasyonlarının incelenmesi tekniğine ne ad verilir?', 'Eğik ışık (raking light / yan ışık) incelemesi', ['Arkadan aydınlatma', 'Gama ışını tomografisi', 'Nötron aktivasyon görüntülemesi'], 'Eğik (teğetsel) ışık yüzey topoğrafyasındaki en ufak kabarma, çanaklaşma, fırça dokusu ve şasi izi gölgelerini büyüterek görünür hale getirir.'),
  ('Bir sanat eserinin yaratıldığı andan günümüze kadar kimlerin elinde bulunduğunu, hangi koleksiyon, müzayede ve kataloglarda yer aldığını gösteren belgeli mülkiyet geçmişine ne ad verilir?', 'Provenans', ['Kraklür morfolojisi', 'İkonografik şema', 'Stratigrafik kesit'], 'Provenans (provenance) araştırması, eserin tarihsel izini arşiv belgeleriyle sürer; boşluklar veya uydurma koleksiyon etiketleri sahtecilik ve kültür varlığı kaçakçılığı soruşturmalarında ilk uyarı işaretidir.'),
  ('Ahşap bir heykelin iç kısmının tahta kurdu larvaları tarafından sünger gibi oyulup kabuğunun çok inceldiği durumlarda, eserin kendi ağırlığıyla çökmesini önlemek için yapılan işleme ne ad verilir?', 'Yapısal sağlamlaştırma', ['Yüzeysel vernik temizliği', 'Lüks seviyesi düşürme', 'Asitsizleştirme banyosu'], 'Böcek galerileriyle zayıflamış ahşaba düşük viskoziteli uygun sentetik reçine çözeltileri (ör. Paraloid B-72 veya Regalrez türevleri) enjekte edilerek iç mekanik direnç yeniden kazandırılır.'),
  ('Bir müzede deprem, yangın, su baskını veya silahlı çatışma gibi olağanüstü durumlarda hangi eserlerin hangi öncelikle, hangi güzergâhtan ve hangi malzemelerle kurtarılacağını önceden planlayan önleyici koruma belgesi hangisidir?', 'Acil durum ve afet yönetim planı', ['Sergi küratöryel metin kataloğu', 'Restorasyon çözücü reçete defteri', 'Müzayede ekspertiz şartnamesi'], 'Önleyici korumanın kritik bir ayağı olan afet hazırlık planı, kriz anında paniği önleyerek koleksiyon kaybını en aza indirecek tahliye ve müdahale protokollerini belirler.'),
  ('Fildişi bir minyatür portre veya oyma eserin doğrudan suyla yıkanmasının kesinlikle yasak olmasının temel fiziksel ve yapısal nedeni nedir?', 'Anizotropik ve çok higroskopik olan fildişinin suyu hızla emip şişmesi, kururken ise büzüşerek ani boyuna çatlaklar oluşturması', ['Fildişinin saf suyla temas ettiğinde şeker gibi birkaç dakikada tamamen erimesi', 'Su moleküllerinin fildişini anında kömür siyahı rengine boyaması', 'Yıkanan fildişinin oda sıcaklığında yumuşayıp hamur kıvamında kalması'], 'Dentin ve kollajen ağından oluşan fildişi neme karşı aşırı duyarlıdır; ıslak temizlik içsel gerilim yaratarak eserin geri dönüşsüz biçimde yarılmasına neden olur.'),
  ('Kâğıt eserlerde "paspartu yanığı" (mat burn) olarak adlandırılan, resmin pencere kenarlarında oluşan kahverengi çerçeve izinin nedeni nedir?', 'Eserle temas eden düşük kaliteli, ligninli mukavva paspartudan kâğıda asit göçü gerçekleşmesi', ['Çerçeve camının büyüteç etkisi yaparak yalnızca kenarları güneşle yakması', 'Paspartuyu kesen bıçağın kenarlara paslı demir tozu bulaştırması', 'Eserin çerçeveye sıcak mum damlatılarak yapıştırılmış olması'], 'Asidik odun hamuru kartonlarından kesilen paspartuların şevli iç kenarları zamanla uçucu asitler ve peroksitler salarak eserde kalıcı kahverengi sınır lekesi bırakır.'),
  ('Bir seramik vazoda eksik olan gövde parçasının alçı ile tamamlandığı arkeolojik konservasyonda, tamamlamanın müze etiği gereği nasıl renklendirilmesi yaygındır?', 'Özgün seramikten bir ton açık/sade tek renkle boyanarak uzaktan formun okunması, yakından ise orijinal parçalardan kolayca ayrılması sağlanır', ['Eksik alçı parçasının üzerine hayali mitolojik sahneler çizilip yapay çatlaklarla eskitilerek orijinalinden farksız kılınır', 'Tamamlanan tüm parçalar dikkat çekmesi için parlak gümüş yaldızla kaplanır', 'Özgün seramik parçalarının tamamı da alçıyla aynı renge boyanarak tekdüze hale getirilir'], 'Arkeolojik seramik bütünlemesinde form bütünlüğü sağlanırken sahte bezeme uydurulmaz; alçı dolgu özgün gövdeyle uyumlu nötr bir tonda bırakılarak dürüstçe ayırt edilir.'),
  ('Çok katmanlı yağlıboya çalışırken boya tabakalarının zamanla çatlamasını önlemek için uygulanan "zayıftan şişmana" (yağsızdan yağlıya) kuralı neyi gerektirir?', 'Her üst katmanda boyaya alt katmandakinden daha fazla yağ eklenmesini', ['İlk katmanda saf keten yağı, son katmanda saf terebentin kullanılmasını', 'Alt katmanların kalın spatula darbeleriyle, üst katmanların sulu sürülmesini', 'Astar üzerine önce vernik atılıp ardından yağsız boya uygulanmasını'], 'Alt katmanların üst katmanlardan daha hızlı ve sert kuruması gerekir; üstteki katman daha esnek (daha yağlı) olmazsa alttaki geç kuruyan yağlı tabaka hareket ettikçe üstteki kırılgan katmanı çatlatır.'),
  ('Keten yağı yerine aspir yağı veya haşhaş tohumu yağı ile üretilmiş beyaz yağlıboyaları tercih eden bir ressamın öncelikli amacı aşağıdakilerden hangisidir?', 'Zamanla oluşabilecek sararma eğilimini en aza indirmek', ['Boyanın kuruma süresini birkaç saate kadar düşürmek', 'Boyayı terebentin kullanmadan doğrudan suyla inceltebilmek', 'Tuval yüzeyinde mat ve tebeşirimsi bir doku oluşturmak'], 'Keten yağı çok sağlam kurusa da zamanla özellikle karanlıkta sararma eğilimi gösterir; haşhaş ve aspir yağları daha geç kurur ancak beyaz ve açık mavi tonlarda sararmayı büyük ölçüde önler.'),
  ('Suluboya üretiminde bağlayıcı olan Arap zamkına az miktarda gliserin veya bal katılmasının temel işlevi nedir?', 'Boyanın tablet veya tüp içinde tamamen kuruyup çatlamasını önleyerek nemli ve esnek kalmasını sağlamak', ['Kuruyan suluboya tabakasını suya karşı tamamen geçirimsiz ve plastik bir yüzeye dönüştürmek', 'Kâğıt yüzeyindeki renklerin şeffaflığını yok edip guaj benzeri tam örtücü bir doku kazandırmak', 'Boyanın keten yağı ve terebentin gibi organik çözücülerle homojen biçimde karışmasını kolaylaştırmak'], 'Gliserin ve bal nem tutucu (higroskopik) maddelerdir; suluboya boyasının taşlaşmasını engeller, fırçayla ıslatıldığında kolayca çözünmesini ve sürüm akışkanlığını artırır.'),
  ('Guaj boya ile yapılmış bir resimde, kuruyan kalın bir boya tabakasının üzerine çok sulu yeni bir katman sürüldüğünde hangi teknik sorunla karşılaşılır?', 'Alttaki kuru guaj tabakası yeniden çözünerek üstteki yeni renge karışır ve lekelenme yapar', ['Üstteki sulu boya plastikleşmiş alt yüzeye tutunamayıp boncuklanarak tuvalden akar', 'İki katman arasındaki kimyasal tepkime nedeniyle boya anında sertleşip fırçayı dondurur', 'Alttaki renk tamamen şeffaflaşarak kâğıdın ham dokusunu yüzeye çıkarır'], 'Guaj boyanın bağlayıcısı olan Arap zamkı kuruduktan sonra da suda çözünür kalır; ıslak fırça darbeleri alttaki kuru guajı uyandırıp üst katmanı bulandırabilir.'),
  ('Suluboya kâğıdında belirli ince detayların geniş fırça yıkamaları (lavaj) sırasında boyanmadan beyaz kalmasını isteyen bir sanatçı hangi yardımcı malzemeyi kullanır?', 'Maskeleme sıvısı', ['Saf çam terebentini çözeltisi', 'Soğuk sıkım keten tohumu yağı', 'Kalsiyum hidroksit kireç kaymağı'], 'Lateks bazlı maskeleme sıvısı kâğıda sürülüp kurutulduğunda suyu iter; üstünden suluboya geçilip kuruduktan sonra silgi gibi soyularak altındaki lekesiz beyaz kâğıt ortaya çıkarılır.'),
  ('Akrilik boyanın çok hızlı kuruma özelliğini açık havada (plein air) çalışırken dezavantaj olarak gören bir ressam, boyanın yapısını bozmadan çalışma süresini uzatmak için boyaya ne katmalıdır?', 'Akrilik geciktirici medyum', ['Saf ispirto veya etil alkol', 'Yumurta akı ve sirke karışımı', 'Kokusuz mineral tiner'], 'Propilen glikol gibi nem tutucular içeren akrilik geciktiriciler (retarder), suyun buharlaşma hızını yavaşlatarak akrilik boyanın palet ve tuval üzerinde açık kalma süresini uzatır.'),
  ('Suluboya kâğıtlarında üretim yöntemine göre "soğuk baskı" (cold press / NOT) olarak adlandırılan yüzeyin temel dokusal özelliği nedir?', 'Hafif dişli, yarı pürüzlü ve hem detaya hem yıkamaya uygun orta doku', ['Ayna gibi pürüzsüz, gözeneksiz ve kaygan yüzey', 'Çok derin çukurlu, kaba çuval görünümünde aşırı pürüzlü doku', 'Balmumu ile kaplanmış su itici parlak katman'], 'Soğuk baskı (cold press) suluboya kâğıtları ısıtılmamış keçeli silindirler arasından geçirildiği için hafif pütürlüdür; pigmenti çukurlarında tutarken detay çalışmaya da izin verir.'),
  ('Sıcak baskı (hot press) suluboya kâğıdının soğuk baskı ve pürüzlü (rough) kâğıtlardan temel farkı ve kullanım alanı nedir?', 'Isıtılmış silindirlerle ütülendiği için çok pürüzsüz olması ve ince botanik illüstrasyonlara uygunluğu', ['Üzerine sıcak balmumu dökülerek su geçirmez hale getirilmiş kalın mukavva olması', 'Yalnızca yağlıboya ve terebentin uygulamaları için keten liflerinden dokunmuş olması', 'Suyu hiç emmediği için boyanın yüzeyde günlerce ıslak kalmasını sağlaması'], 'Sıcak baskı kâğıtlar yüksek ısı ve basınçla pürüzsüzleştirilir; fırça yüzeyde hızla kayar ve ince çizgisel detaylar, taramalar ve botanik resimler için idealdir.'),
  ('Kuru bir suluboya katmanı veya kuru kâğıt üzerine neredeyse hiç su içermeyen az boyalı fırçayı yatay sürterek kâğıdın dokusunu ortaya çıkaran kesikli boyama tekniği hangisidir?', 'Kuru fırça (drybrush)', ['Düz yıkama (flat wash)', 'Dereceli lavaj (graded wash)', 'Sıcak mum akıtma'], 'Kuru fırça tekniğinde fırçadaki az miktarda yoğun boya yalnızca kâğıdın yüksekteki dişlerine (tepeciklerine) değer, çukurlar boş kalır; böylece taş, ağaç kabuğu veya su parıltısı dokusu elde edilir.'),
  ('Akrilik astar veya akrilik boya ile yapılmış tamamen kuru bir alt resmin üzerine yağlıboya uygulanabilmesinin doğru açıklaması nedir?', 'Kurumuş gözenekli akrilik tabakanın yağı hafifçe emerek yağlıboya için sağlam ve esnek bir tutunma zemini sağlaması', ['Yağlıboyadaki keten yağının alttaki kuru akriliği yeniden sıvılaştırarak homojen bir emülsiyon yaratması', 'Akrilik boyanın içindeki terebentinin üstteki yağlıboyayı birkaç dakikada kurutması', 'Su bazlı boyaların her koşulda yağ bazlı boyaların üzerine de altına da sorunsuz sürülmesi'], '"Yağsız üzerine yağlı" ilkesi uyarınca, kuruduğunda yağsız ve mikro-gözenekli kalan akrilik katman üzerine yağlıboya güvenle uygulanabilir; ancak tersi yapılamaz.'),
  ('Yağlıboya resimde son kat verniğin (tablo verniği) esere hemen bitiminde değil de genellikle 6 ila 12 ay sonra sürülmesinin nedeni nedir?', 'Keten yağının derinlemesine oksidasyonla sertleşebilmesi için atmosferdeki oksijenle temasının kesilmemesi gerekliliği', ['Verniğin taze terebentinle temas ettiğinde mor renge dönüşerek tüm tonları bozması', 'İlk aylarda tuval şasisinin büzülüp vernik katmanını kâğıt gibi buruşturması', 'Toz pigmentlerin ışıkla ağararak gerçek rengini ancak bir yıl sonra alması'], 'Son kat vernik yüzeyi hava etkilerine karşı mühürler; boya kütlesi tam sertleşmeden sürülürse alt katmanların oksijen almasını engeller ve vernikte çatlama veya yapışkanlık oluşur.'),
  ('Yağlıboya çalışmalarında "damla sakızı" (dammar) reçinesinin saf terebentin içinde eritilmesiyle elde edilen sıvı temel olarak hangi amaçlarla kullanılır?', 'Resim verniği olarak koruma sağlamak veya keten yağı ve terebentinle karıştırılarak boyama medyumu hazırlamak', ['Ham pamuklu tuval bezini keten yağı asitlerinden korumak için ilk kat izolasyon tutkalı olarak sürmek', 'Kurumuş akrilik fırçalarını plastik kalıntılarından arındırmak için güçlü bir su bazlı çözücü yapmak', 'Suluboya kâğıdının emiciliğini artırmak amacıyla hamurun içine şeffaflaştırıcı olarak katmak'], 'Dammar reçinesi terebentinde çözündüğünde hem geleneksel parlak son kat verniği oluşturur hem de keten yağı-terebentin ikilisine katılarak boyaya parlaklık ve akışkanlık veren medyumlarda yer alır.'),
  ('Akrilik boyaya katıldığında boyanın hacmini, fırça veya spatula izi tutma kapasitesini artıran, yoğun kıvamlı yardımcı malzemeye ne ad verilir?', 'Ağır gövdeli jel medyum / modelaj pastası', ['Saf damıtılmış çam terebentini', 'Soğuk sıkım ceviz yağı', 'Sulu Arap zamkı çözeltisi'], 'Jel medyumlar ve doku/modelaj pastaları (impasto gel, modeling paste), akrilik polimer esaslı yoğun katkılardır; boyanın çökmeden yüksek kabartılı (impasto) sürülmesini sağlar.'),
  ('Yağlıboya veya akrilikte, tamamen kurumuş açık tonlu bir alt katmanın üzerine çok ince, yağlı/medyumlu ve saydam bir boya tabakası sürerek optik renk derinliği yaratma tekniği hangisidir?', 'Glazür (şeffaf katmanlama)', ['Alla prima (tek oturuşta boyama)', 'Kuru sıva üstü secco', 'Kazıma (sgraffito)'], 'Glazür tekniğinde pigment bağlayıcı medyumla inceltilip tül gibi saydam sürülür; ışık bu ince katmandan geçip alttaki katmandan yansıyarak fiziksel karışımda elde edilemeyen derin bir parlaklık üretir.'),
  ('Keten yağının güneşte bekletilerek veya ısıtılarak hava almadan koyulaştırılmasıyla üretilen, fırça izlerini kendiliğinden düzleştiren ve sararması azaltılmış medyum yağ hangisidir?', 'Stand yağ', ['Ham bezir yağı tortusu', 'Uçucu lavanta esansı', 'Rafine edilmemiş balık yağı'], 'Stand yağ (stand oil), keten yağının yüksek ısıda oksijensiz ortamda kısmen polimerize edilmesiyle elde edilir; bal kıvamındadır, glazürlerde pürüzsüz mine yüzeyi verir ve ham keten yağına göre çok az sararır.'),
  ('Suluboya çalışmasında kâğıdın ıslanınca dalgalanıp oluklaşmasını (kabarmasını) önlemek için çalışmaya başlamadan önce yapılan geleneksel hazırlık işlemi nedir?', 'Kâğıdı suya batırıp genleştirdikten sonra kenarlarından zamklı bantla ahşap altlığa gererek kurutmak', ['Kâğıdın her iki yüzünü sıcak keten yağı ile doyurup bir gece pres altında bekletmek', 'Yüzeye kalın bir kat sentetik tiner sürüp gözenekleri tamamen kapatmak', 'Kâğıdı doğrudan metal bir şasiye zımbalayıp üzerine kireç kaymağı sıvamak'], 'Islatılan suluboya kâğıdı lifleri suyu emdiğinde genişler; kenarlarından zamklı şerit bantla (kraft bant) tahtaya yapıştırılıp kuruduğunda davul gibi gerginleşir ve boyama sırasında bir daha dalgalanmaz.'),
  ('Çalışma sırasında palet üzerinde unutulan bir akrilik fırçasının kılları kuruyup taş gibi sertleştiğinde neden normal suyla yıkamak işe yaramaz?', 'Polimer emülsiyon geri dönüşsüz biçimde kaynaşarak suda çözünmeyen katı akrilik reçineye dönüştüğü için', ['Fırça kıllarının içindeki doğal yağlar suyla birleşip boyayı mermerleştirdiği için', 'Akrilik boyanın içindeki Arap zamkı havayla temas edince camlaştığı için', 'Su, kurumuş akrilik boyayla tepkimeye girip fırça kıllarını erittiği için'], 'Akrilik boyadaki su uçtuktan sonra polimer kürecikleri birleşip çapraz/sürekli film oluşturur; bu aşamadan sonra yalnızca özel akrilik fırça temizleyicileri veya alkol bazlı çözücüler plastikleşmiş boyayı yumuşatabilir.'),
  ('Geleneksel yağlıboyadan farklı olarak, terebentin veya tiner gerektirmeden doğrudan suyla inceltilebilen modern yağlıboya türü hangisidir?', 'Suyla karışabilen (water-mixable) yağlıboya', ['Yumurta sarılı tempera boyası', 'Akrilik polimer emülsiyon boyası', 'Zamk bağlayıcılı guaj boyası'], 'Suyla karışabilen yağlıboyalar gerçek keten veya aspir yağı içerir ancak yağ molekülleri emülgatörlerle modifiye edildiği için suyla inceltilebilir; yine de oksidasyonla yavaş kurur.'),
  ('Suluboyada kâğıt üzerindeki boya henüz nemliyken temiz ve hafif nemli bir fırça, sünger veya kâğıt mendille boyayı geri emdirerek bulut ya da ışık huzmesi açma yöntemine ne denir?', 'Kaldırma / silme tekniği', ['Sıcak mumla mühürleme', 'Yağlı glazür katmanlama', 'Kuru sıva aşındırma'], 'Suluboya kâğıt yüzeyine tam nüfuz etmeden veya lekelenme gücü düşük (non-staining) pigmentler kullanıldığında, nemli boya temiz fırça ya da mendille yüzeyden geri çekilerek açık tonlar kurtarılabilir.'),
  ('Guaj boyada ıslakken koyu görünen açık tonların kuruduğunda daha açık, ıslakken parlak görünen çok koyu tonların ise kuruduğunda biraz daha soluk/açık görünmesinin nedeni nedir?', 'Su uçtuğunda boya yüzeyinin matlaşıp ışığı her yöne dağıtması (dağınık yansıma) ve içindeki tebeşir/beyaz dolguların belirginleşmesi', ['Arap zamkının kururken pigmentlerin yarısını buharlaştırarak havaya karıştırması', 'Kâğıdın içindeki selüloz asitlerinin boyadaki tüm koyu pigmentleri ağartması', 'Guajın içindeki akrilik polimerlerin şeffaflaşarak alttaki siyah astarı göstermesi'], 'Islak film ışığı ayna gibi kırarak koyu renkleri derin gösterir; guaj kuruduğunda pürüzlü mikro-yüzeyi ışığı dağıtır, koyular hafifçe grileşir/açılır, açık pastel tonlar da opak dolgu etkisiyle daha da açılır.'),
  ('Yağlıboyada sert ve yoğun kıvamlı boyayı tuvale güçlü fırça darbeleriyle taşımak için geleneksel olarak en uygun fırça kılı hangisidir?', 'Domuz kılı (sert doğal kıl / Chungking bristle)', ['Çok yumuşak sincap kılı', 'İnce samur tüyü (Kolinsky)', 'Pamuk ipliği püskülü'], 'Domuz kılı fırçalar doğal olarak uçları çatallı (flagged), esnek ve serttir; ağır yağlıboyayı fırçada tutar ve keten tuvalin dişli dokusuna kolayca yedirir.'),
  ('Keten tohumlarının ısıtılmadan preslenmesiyle elde edilen ve yağlıboya üreticilerinin en yüksek kalite bağlayıcı saydığı yağ türü hangisidir?', 'Soğuk sıkım (cold-pressed) keten yağı', ['Buharla rafine edilmiş sanayi mazotu', 'Sıcak asitle ağartılmış pamuk yağı', 'Terebentinle seyreltilmiş reçine tortusu'], 'Soğuk sıkım keten yağı kimyasal çözücü veya yüksek ısı görmeden çıkarıldığı için saftır, pigmentleri mükemmel ıslatır ve kuruduğunda en dayanıklı boya filmini oluşturur.'),
  ('Suluboyada "lekelenme yapan" (staining) ftalosiyanin mavisi gibi sentetik organik pigmentlerin, lekelenme yapmayan pigmentlerden uygulama açısından farkı nedir?', 'Kâğıt liflerinin içine anında nüfuz ettiği için kuruduktan sonra ıslak fırçayla silinerek beyaz kâğıda geri dönülememesi', ['Kâğıdın yüzeyinde kalın bir kabuk oluşturup kuruyunca pul pul dökülmesi', 'Suyla temas ettiğinde hiç dağılmayıp yalnızca terebentinle açılması', 'Kuruduktan sonra tamamen opaklaşıp alttaki kurşun kalem çizgilerini kapatması'], 'Çok ince tanecikli sentetik organik pigmentler (phthalo, quinacridone) kâğıt selülozunu boyar; bu yüzden kaldırma (lifting) tekniğinde tamamen temizlenemez, altta iz bırakır.'),
  ('Kuru bir yağlıboya katmanı üzerine yarı-örtücü ve nispeten kuru, açık renkli bir boyayı pürüzlü biçimde sürterek alttaki koyu rengin gözeneklerden kısmen görünmesini sağlayan "kırık renk" tekniği nedir?', 'Scumbling (örtülü sürtme / tülleme)', ['Düz sulu yıkama (lavaj)', 'Sıcak mum damlatma', 'Islak sıva gömme'], 'Glazür koyu ve şeffaf boyayla yapılırken, scumbling genellikle açık ve opak/yarı-opak boyanın kuru fırçayla ince ve kesikli sürülerek alt katmanla optik bir pus yaratmasıdır.'),
  ('Tüp suluboya ile tablet (pan) suluboya karşılaştırıldığında, çok büyük boyutlu bir kâğıtta geniş ve yoğun renkli yıkamalar yapacak bir sanatçı neden tüp suluboyayı tercih eder?', 'Tüpteki nemli boyanın büyük miktarlarda suyla çok daha hızlı çözünüp fırçayı aşındırmadan yoğun renk karışımı vermesi', ['Tablet suluboyanın kuruduktan sonra su geçirmez olup kâğıda hiç yayılmaması', 'Tüp suluboyanın keten yağı içerdiği için tuval üzerinde kabartma yapabilmesi', 'Tablet suluboyanın yalnızca siyah-beyaz eskizler için üretilmesi'], 'Büyük alanlar için gereken bol boyayı küçük katı tabletten ovalayarak çıkarmak zaman alır ve samur fırçayı yıpratır; tüp boya palete sıkılıp anında bol ve doygun lavaj suyuna dönüşür.'),
  ('Yağlıboyada keten yağının yanında inceltici ve parlatıcı olarak kullanılan, iğne yapraklı Venedik karaçamından elde edilen koyu kıvamlı doğal balzam hangisidir?', 'Venedik terebentini', ['Saf aseton ruhu', 'Sentetik akrilik jel', 'Akasya Arap zamkı'], 'Normal akışkan çam terebentininden farklı olarak Venedik terebentini bal kıvamında bir oleoreçinedir; yağlıboya medyumlarına az miktarda katıldığında mine parlaklığı ve pürüzsüz akış sağlar.'),
  ('Akrilik boya ile çalışırken boyanın palet üzerinde çalışma boyunca kurumaması için tasarlanmış özel palet sisteminin çalışma prensibi nedir?', 'Islak bir sünger katmanı üzerine yerleştirilen yarı-geçirgen yağlı/parşömen kâğıdın alttan boyaya sürekli mikroskobik nem sağlaması', ['Paletin altından elektrikli rezistansla ısı verilerek polimerlerin sıvı tutulması', 'Palet yüzeyinin keten yağı ve terebentin havuzuyla kaplanması', 'Boyaların üzerine her beş dakikada bir kireçli su püskürtülmesi'], '"Islak palet" (stay-wet palette) düzeneğinde alttaki ıslak süngerden yarı-geçirgen özel kâğıda sızan nem, akrilik boyadaki suyun uçmasını önleyerek boyayı günlerce kullanılabilir tutar.'),
  ('Yağlıboyada çam terebentini yerine tarihsel olarak bazı ustaların tercih ettiği, daha yavaş buharlaşan ve çam alerjisi yapmayan bitkisel uçucu yağ hangisidir?', 'Lavanta başak yağı (spike oil)', ['Tatlı badem yağı', 'Hint yağı (castor oil)', 'Zeytin pirina yağı'], 'Yabani lavantadan (Lavandula latifolia) damıtılan başak yağı (oil of spike lavender), terebentin gibi tamamen uçucu bir çözücüdür; reçineleri çözer ve yağlıboyayı hoş kokuyla inceltir.'),
  ('Suluboya kâğıtlarının ağırlığını belirten "300 g/m²" (gsm) ifadesi kâğıdın hangi fiziksel niteliğini tanımlar?', 'Bir metrekare büyüklüğündeki tek bir kâğıt tabakasının gram cinsinden kütlesini', ['Kâğıdın bir santimetrekaresinin emebileceği en yüksek su miktarını', 'Kâğıt hamuruna katılan Arap zamkı ve keten yağının toplam ağırlığını', 'Kâğıdın yırtılmadan önce dayanabileceği çekme kuvvetini'], '300 g/m² (yaklaşık 140 lb), suluboyada standart ağır gramaj kabul edilir; düşük gramajlı (ör. 180 g/m²) kâğıtlara kıyasla çok daha kalın ve tok olduğundan ıslakken çok daha az kabarır.'),
  ('Guaj boyayla çalışırken alt katmandaki rengin üst katmana bulaşmasını (kanama/kalkma) en aza indirmek için fırça kullanımında hangi yöntem izlenmelidir?', 'Alt katman tamamen kuruduktan sonra biraz daha kıvamlı boyayı tek ve kendinden emin, yumuşak kıllı fırça darbesiyle fazla ovalamadan sürmek', ['Alt katmanı önce terebentinle ıslatıp sert domuz kılı fırçayla dairesel olarak kazımak', 'Her katmanın arasına kalın bir tabaka keten yağı sürüp iki gün beklemek', 'Üst katmanı çok bol kaynar suyla incelterek aynı noktadan on kez geçmek'], 'Guaj suyla yeniden çözündüğü için sert fırçayla aynı yeri defalarca ileri geri ovalamak alt katmanı kaldırır; yumuşak sentetik/samur fırçayla tek hamlede bırakmak bulaşmayı önler.'),
  ('Ceviz yağının (walnut oil) yağlıboya incelticisi ve bağlayıcısı olarak keten yağıyla karşılaştırıldığında öne çıkan avantaj ve sınırlılığı nedir?', 'Keten yağından daha akışkan olması ve daha az sararması, buna karşın biraz daha yavaş kuruması ve rafta bayatlamaya daha yatkın olması', ['Keten yağından on kat hızlı kuruması, ancak kuruduğunda tüm renkleri koyu kahverengiye çevirmesi', 'Suyla doğrudan karışabilmesi, ancak tuval üzerinde hiçbir zaman katılaşmaması', 'Terebentin gibi uçucu olması, ancak insan derisine değdiğinde yanık oluşturması'], 'Leonardo da Vinci gibi Rönesans ustalarının da sevdiği ceviz yağı açık renklidir, terebentin gerektirmeden boyayı inceltir ve az sararır; ancak keten yağı kadar hızlı ve sert bir film kurmaz.'),
  ('Suluboyada kuru bir boya katmanının üzerine ikinci bir şeffaf boya katmanı sürülerek keskin kenarlı üst üste binmeler ve optik renk karışımları elde edilen temel teknik hangisidir?', 'Kuru üstüne ıslak', ['Islak üstüne ıslak dağılma', 'Kuru kireç kazıma', 'Kalın spatula kabartması'], 'Alt katman tamamen kuruduktan sonra üzerine sürülen şeffaf suluboya yayılmaz, keskin sınırlarını korur ve alttaki renkle optik olarak birleşerek üçüncü bir ara ton oluşturur.'),
  ('Orta Çağ ve Erken Rönesans\'ta yumurta temperası çalışmalarının esnek keten tuval yerine kalın ahşap paneller (kavak veya ıhlamur ağacı) üzerine yapılmasının temel nedeni nedir?', 'Geleneksel alçı-tutkal gessosunun ve kuruyan yumurta sarısı filminin esnek olmaması nedeniyle sallanan tuvalde hızla çatlayacak olması', ['Ahşap panellerin suyu sünger gibi emerek temperanın kurumasını bir aya uzatması', 'O dönemde keten ve kenevir bitkilerinden kumaş dokunmasının henüz bilinmemesi', 'Yumurta sarısının pamuk lifleriyle temas ettiğinde kumaşı anında eritmesi'], 'Hem geleneksel gesso (tutkal + tebeşir/alçı) hem de tamamen kurumuş yumurta temperası sert ve kırılgan yapıdadır; esnek bez üzerinde çatlayacağı için rijit (esnemeyen) ahşap paneller zorunluydu.'),
  ('Yumurta temperası hazırlarken yumurta sarısını zarından ayırıp yalnızca içindeki sıvı sarıyı kullanmanın boya kalitesi açısından önemi nedir?', 'Yumurta zarının boya içinde çözünmeyen pıhtılar ve fırça izini bozan lifli kalıntılar bırakmasını önlemek', ['Zar çıkarılmazsa boyanın renginin parlak maviye dönüşmesini engellemek', 'Yumurta zarının keten yağıyla tepkimeye girip tuvali yakmasını durdurmak', 'Zarın boyayı tamamen şeffaflaştırarak verniğe çevirmesini önlemek'], 'Yumurta sarısı avuçta yuvarlanıp kurulanır, ardından zar delinerek yalnızca saf sıvı sarı akıtılır; zar parçaları boyaya karışırsa pürüzsüz tempera yüzeyinde pütür ve soyulma yaratır.'),
  ('Enkostik (sıcak balmumu) tekniğinde boya ahşap panele fırça veya spatulayla sürüldükten hemen sonra yüzeye kontrollü sıcak hava tabancası veya meşale tutulmasının ("kaynaştırma" / fusing) amacı nedir?', 'Yeni sürülen mum katmanını alttaki katmanla eriterek birbirine kenetlemek ve katmanların soyulmasını önlemek', ['Balmumunun tamamını buharlaştırıp geride yalnızca kuru toz pigment bırakmak', 'Ahşap paneli kömürleştirerek doğal siyah bir arka plan elde etmek', 'Mumun içindeki suyu kaynatıp gözenekli sünger dokusu yaratmak'], 'Enkostikte "fusing" (ısıl kaynaştırma) yapılmazsa soğuk alt katmanın üzerine sürülen sıcak mum tam yapışamaz ve zamanla pul halinde ayrılır; hafif ısıtma katmanları tek vücut yapar.'),
  ('Yaş fresk (buon fresco) uygulamasında sanatçının tek bir iş gününde boyayabileceği kadar taze ince sıva sürdüğü bölümlere sanat tarihinde ne ad verilir?', 'Giornata (günlük çalışma alanı)', ['Arriccio (kaba alt sıva)', 'Sinopia (kızıl ön çizim)', 'Chiaroscuro (gölgeleme)'], 'İtalyanca "gün" (giorno) kelimesinden gelen giornata, sıva kurumadan o gün içinde bitirilebilecek boyuttaki sıva yamasıdır; örneğin karmaşık bir yüz bir tam giornata olabilirken düz gökyüzü geniş bir giornata olur.'),
  ('Yaş fresk duvar hazırlığında taş veya tuğla duvarın üzerine ilk kat olarak atılan kaba kumlu kireç sıvası (arriccio) üzerine kırmızı toprak boyayla yapılan anıtsal ön taslak çizimine ne denir?', 'Sinopia', ['İntonaco', 'Sgraffito', 'Grisaille'], 'Karadeniz\'deki Sinop kentinden adını alan kızıl toprak pigmentiyle (Sinop kırmızısı) kaba sıva üzerine çizilen kompozisyon taslağına sinopia denir; üstüne son kat ince sıva (intonaco) parça parça sürülür.'),
  ('Geleneksel yağlıboya zemin hazırlığında, gesso veya yağlı astar sürülmeden önce ham keten bezin gözeneklerini tıkayıp yağ asitlerine karşı ilk yalıtımı yapmak için sıcak olarak sürülen hayvansal madde nedir?', 'Tavşan derisi tutkalı', ['Saf balmumu ve çam reçinesi', 'Terebentinde erimiş dammar', 'Soğuk sıkım haşhaş yağı'], 'Geleneksel yöntemde keten bez önce ılık tavşan derisi tutkalı (rabbit skin glue) ile haşıllanır (sizing); bu katman kumaşı gerginleştirir ve üstüne sürülecek yağlı astarın liflere sızmasını engeller.'),
  ('Tuval kumaşı olarak keten bezin (linen) pamuklu beze (cotton duck) göre profesyonel ve müzelik eserlerde daha üstün kabul edilmesinin temel nedeni nedir?', 'Keten liflerinin pamuktan çok daha uzun, güçlü, nem değişimlerinde sarkmaya dirençli ve kendi doğal yağlarıyla daha dayanıklı olması', ['Keten bezin hiçbir astar veya gesso gerektirmeden yağlıboyayı doğrudan tutması', 'Pamuklu bezin üzerine akrilik boya sürüldüğünde anında erimesi', 'Keten kumaşın tamamen pürüzsüz plastikten dokunması'], 'Keten bitkisinin sap lifleri pamuğun kısa tohum liflerine göre çok daha sağlamdır, gerilme direnci yüksektir ve atmosferik nem dalgalanmalarında çok daha az gevşeme/kasılma yapar.'),
  ('Ahşap bir paneli geleneksel gesso veya akrilik gesso ile astarlarken, panelin zamanla içbükey/dışbükey olarak bel vermesini (çarpılmasını) azaltmak için hangi önlem alınır?', 'Panelin yalnızca ön yüzüne değil, arka yüzüne ve kenarlarına da eşit nem dengesi sağlayacak şekilde astar/izolasyon katmanı uygulamak', ['Paneli boyamadan önce üç gün kaynar su dolu küvette bekletmek', 'Ahşabın ön yüzüne çok kalın gesso sürüp arka yüzünü ıslak süngerle bırakmak', 'Panelin ortasını matkapla delerek hava akışı sağlamak'], 'Ahşabın yalnız tek yüzü su bazlı astarla kaplanırsa ön ve arka yüz atmosferik nemi farklı hızlarda alıp verir; bu dengesiz genleşme ahşabı eğer (cradling veya çift taraflı yalıtım bunu dengeler).'),
  ('Tuval bezini ahşap şasiye zımbalarken bezde kırışıklık veya köşegen dalgalanma olmaması için zımbalama işlemine hangi sırayla başlanmalıdır?', 'Her dört kenarın tam ortasından karşılıklı gererek başlayıp merkezden köşelere doğru simetrik ilerlemek', ['Sol üst köşeden başlayıp saat yönünde çepeçevre tek seferde dönmek', 'Önce dört köşeyi sıkıca çivileyip ortadaki bolluğu ütüyle eritmek', 'Bezi rastgele zımbalayıp üzerine sıcak keten yağı dökerek düzleştirmek'], 'Elmas/artı düzeninde önce uzun ve kısa kenarların tam merkezleri karşılıklı çekilip sabitlenir, ardından merkezlerden köşelere doğru karşılıklı eşit gerginlikle ilerlenir; son olarak köşeler zarf gibi katlanır.'),
  ('Enkostik çalışmalarında kullanılan geleneksel zemin yüzeyinin fazla parlak ve kaygan olmaması, sıcak balmumunu hafifçe emerek kilitlemesi için en uygun panel yüzeyi hangisidir?', 'Ham ahşap veya alçı/tebeşir esaslı emici "enkostik gesso" sürülmüş gözenekli ahşap panel', ['Akrilik polimerle parlak plastikleştirilmiş kaygan branda', 'Keten yağı ve dammar verniğiyle mühürlenmiş yağlı tuval', 'Yağlı parşömen kâğıdı kaplı esnek karton'], 'Akrilik gesso ısıtıldığında yumuşayıp balmumunu itebilir ve zayıf tutunma sağlar; oysa ham ahşap veya tavşan derisi tutkalı-tebeşir bazlı emici enkostik gesso erimiş mumu gözeneklerine çeker.'),
  ('Yumurta temperasına bir miktar keten yağı (veya stand yağ ile dammar reçinesi) eklenerek oluşturulan "tempera grassa" (yağlı tempera) emülsiyonunun klasik saf temperaya göre sağladığı avantaj nedir?', 'Saf temperadan biraz daha yavaş kuruması, daha doygun koyu tonlar vermesi ve daha esnek/yarı-saydam geçişlere olanak tanıması', ['Su kullanmadan yalnızca saf terebentinle kâğıt üzerinde çalışılabilmesi', 'Islak kireç sıvasının içine gömülerek yaş fresk gibi taşlaşması', 'Isıtılmadan sürülemeyen katı mum kalıplarına dönüşmesi'], 'Tempera grassa, yumurta sarısının emülgatör gücüyle su ve kuruyucu yağı birleştirir; hem suyla inceltilebilir hem de yağlıboyaya yaklaşan optik derinlik ve esneklik sunar.'),
  ('Yaş fresk ile boyanmış tarihi bir duvar resminde iki "giornata" (günlük sıva bölümü) arasındaki ek yerlerinin eğik ışıkta incelendiğinde uzmanlarca fark edilebilmesi neyi ortaya koyar?', 'Sanatçının freski hangi sırayla, yukarıdan aşağıya ve kaç iş gününde tamamladığının kronolojik haritasını', ['Resmin yaş fresk değil, tuval üzerine yağlıboya yapılıp duvara yapıştırıldığını', 'Duvarın deprem nedeniyle çatlayıp sonradan çimentoyla yamandığını', 'Kullanılan tüm pigmentlerin sentetik plastikten üretildiğini'], 'Yeni günün ıslak sıvası bir önceki günün kurumuş ve kesilmiş sıva kenarının yanına hafifçe bindirilerek sürülür; yan ışıkta görülen bu hafif kabartı sınırları ustanın çalışma takvimini ele verir.'),
  ('Tuval veya panel üzerine renkli bir ilk zemin oluşturmak amacıyla astarın üstüne ince ve şeffaf bir toprak rengiyle sürülen tek renkli yıkama katmanına yağlıboyada ne ad verilir?', 'İmprimatura (renkli zemin mührü)', ['Sinopia (duvar ön çizimi)', 'Alla prima (doğrudan bitirme)', 'Enkostik (balmumu eritme)'], 'Göz alıcı beyaz gessonun ton yargısını yanıltmasını önlemek için tuval yüzeyine terebentinle inceltilmiş çiğ umbra, yanık sienna veya gri tonla atılan yarı-saydam ilk zemin lekesine imprimatura denir.'),
  ('Sütteki pıhtılaşmış proteinden (lor/kazein) sönmüş kireç veya amonyum karbonat yardımıyla elde edilen, kuruduğunda mat, sert ve neme oldukça dirençli antik boya bağlayıcısı hangisidir?', 'Kazein', ['Arap zamkı', 'Keten yağı', 'Polimer jel'], 'Kazein boyası, yağsız süt loru proteininin alkali bir maddeyle çözülmesiyle yapılır; hızlı kurur, guaj gibi kadifemsi mat görünür ama kuruduktan sonra guajdan çok daha suya dayanıklıdır ve panel üzerinde kullanılır.'),
  ('Yeni hazırlanan yumurta temperası emülsiyonunun oda sıcaklığında birkaç gün içinde kokup bozulmasını geciktirmek için geleneksel tariflerde karışıma birkaç damla ne eklenir?', 'Üzüm sirkesi, beyaz şarap veya karanfil yağı', ['Saf çam terebentini ve mazot', 'Kalsiyum karbonat tebeşir tozu', 'Sıcak eritilmiş parafin mumu'], 'Cennino Cennini döneminden beri bilinen yöntemlerde sirke (asetik asit), şarap veya doğal antiseptik olan karanfil yağı yumurta sarısının bakteriyel bozulmasını yavaşlatır ve yüzey gerilimini düşürür.'),
  ('Yaş fresk çalışmasında "karton" (cartone) adı verilen tam boy kâğıt taslağın ana hatlarını ıslak sıva üzerine aktarmak için çizgiler boyunca iğneyle delikler açıp kömür tozu dolu keseyle vurma tekniğine ne denir?', 'Tozlama / silkeleme', ['Sıcak mumla dağlama', 'Islak süngerle silme', 'Kuru fırçayla tarama'], 'İtalyanca spolvero tekniğinde delikli taslak kâğıdı yaş sıva üzerine tutulur ve tülbent içindeki kömür tozu kesesi deliklere hafifçe vurularak noktalı kılavuz konturlar sıvaya geçirilir.'),
  ('Enkostik boyaya sertlik kazandırmak, erime noktasını biraz yükseltmek ve soğuduktan sonra yüzeyin yumuşak bezle parlatılabilmesini sağlamak için balmumuna hangi doğal madde katılır?', 'Dammar reçinesi kristalleri', ['Saf gliserin şurubu', 'Tavşan derisi tutkalı', 'Sönmüş kireç tozu'], 'Saf arı balmumu nispeten yumuşaktır ve toz tutabilir; genellikle %10-20 oranında dammar reçinesiyle birlikte eritildiğinde ("encaustic medium") çizilmeye dirençli ve mine gibi parlatılabilir bir yüzey verir.'),
  ('Tuval bezini şasiye gererken el gücünün yetmediği gerginliği sağlamak ve bez kenarını yırtmadan geniş ağızla kavrayıp şasi sırtına dayayarak çekmek için kullanılan el aleti hangisidir?', 'Tuval germe pensesi', ['Kargaburun tel kesici', 'Ahşap oyma iskarpelası', 'Silikon boya merdanesi'], 'Geniş ve tırtıklı/kauçuklu çenelere sahip tuval germe pensesi, alt çenesindeki destek çıkıntısını şasi çıtasına dayayıp kaldıraç etkisiyle bezin eşit ve gergin çekilmesini sağlar.'),
  ('Şeffaf suluboya yapmak isteyen bir sanatçı neden standart akrilik gesso sürülmüş bir tuvalde kâğıttaki gibi sonuç alamaz ve bunun için hangi özel astarı kullanmalıdır?', 'Standart gesso suyu yeterli ve dengeli emmediği için suluboya yüzeyde boncuklanıp kayar; bu nedenle yüksek emicili özel "suluboya gessosu" (watercolor ground) sürülmelidir', ['Standart gesso su değdiği anda çözünüp suluboyayı beyaza boyar; bu nedenle keten yağı sürülmelidir', 'Suluboya yalnızca karanlıkta kuruduğu için siyah yağlı astar kullanılmalıdır', 'Tuval bezi suyu gördüğünde alev aldığı için metal levha seçilmelidir'], 'Normal akrilik gesso plastik reçine oranı nedeniyle suluboya için fazla kapalıdır; özel "absorbent/watercolor ground" astarlar pamuk kâğıt benzeri mikro-gözenekli dokusuyla suluboyayı tutar.'),
  ('Yağlıboyada geleneksel keten yağı yerine sentetik olarak modifiye edilmiş yağlı polyester reçineler kullanılarak üretilen ve kuruma süresini 18-24 saate indiren yağlıboya/medyum grubu hangisidir?', 'Alkid yağlıboya / alkid medyum', ['Saf haşhaş yağı serisi', 'Yumurta akı temperası', 'Arap zamklı guaj'], 'Alkid reçineleri yağla modifiye edilmiş sentetik bağlayıcılardır; geleneksel keten yağlı boyalarla tamamen uyumlu karışır, tüm katmanların eşzamanlı ve hızlı (yaklaşık bir günde dokunma kuruluğunda) sertleşmesini sağlar.'),
  ('Ahşap panel olarak MDF veya kontraplak üzerine akrilik gesso sürmeden önce, ahşabın içindeki tanen ve reçine asitlerinin zamanla beyaz gessoyu sarı-kahverengi lekelememesi ("kusma" / SID) için ne sürülmelidir?', 'İzolasyon katmanı', ['Bol miktarda saf su ve gliserin', 'Soğuk sıkım ceviz yağı', 'Sulandırılmış guaj boyası'], 'Ham ahşap ve MDF levhalar su bazlı gesso sürüldüğünde içlerindeki suda çözünen kahverengi lignini/asitleri yüzeye kusar (Support Induced Discoloration); şeffaf akrilik izolasyon medyumu bu geçişi bloke eder.'),
  ('Tuval bezinin sadece ön yüzünden değil, ahşap şasinin yan derinliklerinden dolandırılıp şasinin arka yüzüne zımbalanmasıyla çerçevenin gereksiz kılındığı modern tuval tipine ne ad verilir?', 'Galeri tipi (arkadan zımbalı / derin kenarlı) tuval', ['Kâğıt maruflajlı eskiz bloğu', 'Kuru sıva secco paneli', 'Geleneksel ikona tahtası'], 'Yandan zımbalı standart tuvaller çerçeve gerektirirken, galeri sarımlı (gallery-wrapped) tuvaller genellikle kalın şasili olup zımbaları arkada gizler; böylece yan kenarlar da boyanarak çerçevesiz sergilenebilir.'),
  ('Enkostik tekniğinde soğumuş balmumu yüzeyine sivri uçlu metal kalemlerle çizgiler kazıyıp bu oyuklara farklı renkte sıcak veya macunsu boya doldurup fazlalığı sıyırma işlemine ne denir?', 'Kakma / oygu doldurma', ['Islak üstüne ıslak suluboya', 'Yaş sıva karbonatlaştırma', 'Kuru fırça tülleme'], 'Balmumunun hacimli ve oyulabilir yapısı sayesinde soğuk yüzeye açılan kanallara kontrast renkli mum doldurulup yüzey kazındığında (scraping back) jilet keskinliğinde grafik çizgiler elde edilir.'),
  ('Bir sanatçı hızlı kuruyan, suyla inceltilebilen, kuruduğunda esnek ve suya dayanıklı kalan, hem şeffaf suluboya gibi akıtılabilen hem de kalın spatula kabartmalarına ve kolaja izin veren tek bir çok yönlü boya sistemi aramaktadır; hangi boya türü bu gereksinimlerin tümünü karşılar?', 'Su bazlı akrilik boya', ['Saf keten yağlı geleneksel yağlıboya', 'Arap zamkı bağlayıcılı geleneksel guaj', 'Sıcak balmumu esaslı enkostik boya'], 'Yağlıboya geç kurur ve suyla inceltilemez; guaj kalın sürülürse çatlar ve kuruyunca suda çözünür; enkostik ısıtma ve rijit panel ister; yalnızca akrilik polimer sistemi uygun medyumlarla tüm bu teknikleri tek çatı altında sunar.'),
  ('Sarı aşı boyasının (sarı okr) yüksek sıcaklıkta fırınlanarak suyunun uzaklaştırılması (kalsinasyon) sonucunda hangi pigment elde edilir?', 'Kırmızı aşı boyası', ['Prusya mavisi', 'Kurşun beyazı', 'Doğal ultramarin'], 'Hidrate demir oksit (götit) içeren sarı okr ısıtıldığında suyunu kaybederek susuz demir okside (hematit), yani kırmızı okr tonuna dönüşür.'),
  ('Doğal zencefre mineralinin öğütülmesi dışında, Orta Çağ\'dan itibaren cıva ve kükürdün kapalı kapta ısıtılıp süblimleştirilmesiyle üretilen pigment hangisidir?', 'Yapay vermilyon', ['Yanık sienna', 'Fransız ultramarini', 'Çinko sarısı'], 'Kuru süreç (dry process) adı verilen yöntemle cıva ve kükürt birleştirilip ısıtılarak doğal zencefre ile aynı kimyasal yapıdaki sentetik vermilyon üretilmiştir.'),
  ('Lapis lazuli taşının içindeki kalsit ve pirit gibi yabancı mineralleri ayıklayıp saf mavi pigmenti elde etmek için Cennino Cennini\'nin tarif ettiği geleneksel yöntem nedir?', 'Öğütülmüş taşı balmumu, çam reçinesi ve yağ ile yoğurup küllü ılık suda yıkayarak maviyi süzmek', ['Taşı nitrik asit içinde eritip dibe çöken altın pirit kristallerini mıknatısla toplamak', 'Lacivert taşını açık ateşte kor haline gelene kadar yakıp soğuk sirke içine atarak çatlatmak', 'Toz haline getirilen cevheri cıva ile karıştırıp keten bezlerden yüksek basınçla geçirmek'], 'Pastiglia adı verilen hamur yönteminde hidrofilik lazurit kristalleri suyla yıkanınca dışarı çıkar, safsızlıklar ise mum-reçine hamurunda hapsolur.'),
  ('Kurşun plakaların kapalı toprak kaplarda sirke buharı ve fermente olan hayvan gübresinin yaydığı karbondioksit etkisinde bırakılmasıyla kurşun beyazı üretilen tarihsel yönteme ne ad verilir?', 'Hollanda yöntemi', ['Kayıp mum yöntemi', 'Bessemer süreci', 'Solvay yöntemi'], 'Klasik Hollanda (istif/stack) yönteminde asetik asit buharı ve gübreden çıkan ısı ile karbondioksit, metalik kurşunu bazik kurşun karbonata dönüştürür.'),
  ('1826 yılında Fransız kimyager Jean-Baptiste Guimet\'nin kil, soda, kükürt ve kömürü fırınlayarak düşük maliyetle ürettiği sentetik boya maddesi hangisidir?', 'Fransız ultramarini', ['Prusya mavisi', 'Kadmium kırmızısı', 'Kobalt yeşili'], 'Lapis lazulinin pahalılığı üzerine açılan yarışmayı kazanan Guimet, kimyasal olarak lazuritle özdeş olan yapay (Fransız) ultramarini sentezlemiştir.'),
  ('Japon resim sanatı ukiyo-e ahşap baskılarında (örneğin Hokusai\'nin Büyük Dalga eserinde) devrim yaratan ve ithal edilerek geleneksel bitkisel çivit boyasının yerini alan pigment hangisidir?', 'Prusya mavisi', ['Lapis lazuli', 'Mısır mavisi', 'Malakit yeşili'], 'Edo dönemi sonlarında Hollandalı tüccarlar aracılığıyla Japonya\'ya ulaşan Prusya mavisi (bero-ai), solmayan derin tonlamalarıyla ukiyo-e baskılarını dönüştürmüştür.'),
  ('Sıkıştırılmış (komprese) füzenin geleneksel söğüt füzeninden temel yapısal farkı nedir?', 'Toz kömürün kil veya zamk bağlayıcı ile preslenerek çok daha koyu, sert ve zor silinen bir yapı kazanması', ['İçine balmumu ve bezir yağı katıldığı için yalnızca tuval üzerine uygulanabilmesi', 'Hematit minerali eklendiği için kağıt üzerinde kızıl-kahverengi izler bırakması', 'Sadece suyla ıslatıldığında renk veren çözünür karbon kristallerinden üretilmesi'], 'Söğüt füzeni dalın doğrudan kömürleşmiş haliyken, sıkıştırılmış füzen bağlayıcı ile preslendiğinden kadifemsi derin siyahlar verir ancak zor silinir.'),
  ('Kayıp mum bronz döküm tekniğinde erimiş metalin kalıbın her noktasına ulaşmasını sağlayan kanallara ve içerideki havanın dışarı çıkmasına yarayan bacalara ne ad verilir?', 'Yolluk ve hava kanalları', ['Armatür ve şasi', 'Patina ve vernik', 'Keski ve murç'], 'Döküm sırasında sıvı bronzun aktığı giriş kollarına yolluk (sprue/runner), sıkışan gazların kalıbı çatlatmadan kaçtığı kanallara ise hava bacası (vent) denir.'),
  ('Kuru pastel ressamlarının renklerin parlaklığını ve mat kadifemsi dokusunu bozmamak için fiksatifi nasıl uygulamaları önerilir?', 'Son katmanda aşırıya kaçmadan, ağırlıklı olarak ara katmanlarda uzak mesafeden ince sis halinde püskürterek', ['Fırçayla kalın bir tabaka halinde doğrudan bitmiş resmin tamamına sürerek', 'Pastel çubuklarını çizim öncesinde sıvı fiksatif kavanozunun içinde on dakika bekleterek', 'Kağıdın yalnızca arka yüzünü terebentin ve bezir yağı karışımıyla tamamen ıslatarak'], 'Yoğun fiksatif kuru pastelin kırılma indisini değiştirip renkleri koyulaştırdığından, ara katmanlarda hafifçe uygulanıp son katmanda minimumda tutulur.'),
  ('Mermer heykel yontuculuğunda kaba kütle atıldıktan sonra yüzeyde paralel diş izleri bırakarak formu adım adım incelten taraklı çelik keskiden ne diye söz edilir?', 'Dişli kalem', ['Ebeşuar', 'Sistire', 'Modelaj teli'], 'Dişli kalem (gradina/claw chisel), sivri murç (haşlama kalemi) ile düz kalem arasındaki aşamada mermeri çatlatmadan kontrollü aşındıran taraklı keskidir.'),
  ('Bronz dökümde heykelin tamamen dolu ve aşırı ağır olmasını, ayrıca soğurken çatlamasını önlemek amacıyla mum modelin iç kısmında bırakılan ateşe dayanıklı kütleye ne denir?', 'Maça', ['Patina', 'Fiksatif', 'Zımpara'], 'Maça (çekirdek/core), kil, alçı ve kum karışımından yapılan iç dolgu kütlesidir; dıştaki kalıp ile maça arasındaki ince mum boşluğu bronzun et kalınlığını belirler.'),
  ('Yağlı pastelin 20. yüzyıl başında sanatsal kalitede geliştirilmesinde hangi ünlü ressamın Henri Sennelier\'den her yüzeyde çalışabilecek yoğun renkli çubuklar talep etmesi etkili olmuştur?', 'Pablo Picasso', ['Claude Monet', 'Rembrandt van Rijn', 'Michelangelo Buonarroti'], 'Öğrenci işi mumlu pastellerin ötesinde profesyonel bir malzeme arayan Picasso\'nun isteği üzerine Sennelier yüksek pigmentli sanatsal yağlı pasteli üretmiştir.'),
  ('Fresk (yaş sıva) tekniğinde yapılan duvar resimlerinde doğal ultramarin veya Prusya mavisi yerine genellikle azurit veya kuru sıva (secco) tercih edilmesinin kimyasal gerekçesi nedir?', 'Prusya mavisinin taze kirecin yüksek bazik (alkali) ortamında bozunup kahverengiye dönmesi, ultramarinin ise yaş sıvada tutunmasının maliyetli olması', ['Yaş kireç sıvasının her iki mavi pigmentle birleştiğinde zehirli cıva buharı açığa çıkarması', 'Kalsiyum hidroksitin mavi kristalleri anında eriterek duvar yüzeyinde derin oyuklar açması', 'Sıva kururken bu iki pigmentin havadaki azotla birleşip parlak vermilyon kırmızısına dönüşmesi'], 'Prusya mavisi alkali ortamlara (kireç sıvasına) karşı dayanıksız olup demir okside (kahverengiye) dönüşür; değerli ultramarin ise fresk yerine sonradan tutkallı bağlayıcıyla kuru sıvaya sürülürdü.'),
  ('Yağlı boya tekniğinde kurşun beyazının yüzyıllarca çinko ve titanyum beyazına göre rakipsiz kalmasını sağlayan reolojik ve kimyasal özelliği nedir?', 'Bezir yağı ile kurşun sabunları oluşturarak hızlı kuruyan, esnek ve çatlamaya dirençli dayanıklı bir boya filmi yaratması', ['Hiçbir kimyasal tepkimeye girmeden yağın içinde asılı kalarak boyanın yıllarca ıslak kalmasını sağlaması', 'Güneş ışığı görmeyen karanlık ortamlarda bile hiç sararmadan soğuk mavimsi bir parlaklık yayması', 'Su ile kolayca inceltilebildiği için fırçaların temizliğinde organik çözücü ihtiyacını ortadan kaldırması'], 'Kurşun iyonları kuruyan yağlardaki yağ asitleriyle çapraz bağlar ve metal sabunları kurarak hem kuruma süresini kısaltır hem de elastik, sağlam bir katman oluşturur.'),
  ('Tarihsel tablolarda vermilyon ile boyanmış parlak kırmızı kumaşların bazı bölgelerinde zamanla kararma ve gri-siyah lekeler görülmesinin nedeni nedir?', 'Işık ve klorür iyonlarının etkisiyle kırmızı cıva sülfürün (alfa-HgS) kristal yapısının siyah metasinabara (beta-HgS) dönüşmesi', ['Vermilyonun içindeki demir oksit taneciklerinin atmosferdeki oksijenle paslanarak kömürleşmesi', 'Tuval astarındaki kalsiyum karbonatın kırmızı pigmenti emerek alttaki füzen çizimini yüzeye çıkarması', 'Ressamın kırmızı rengi koyulaştırmak için boyaya aşırı miktarda çini mürekkebi karıştırması'], 'Cıva sülfür ışığa ve ortamdaki halojen safsızlıklara maruz kaldığında kristal kafesi değişerek kırmızı zencefreden siyah metasinabar formuna geçer.'),
  ('Sulu boya veya guaj tekniğinde kurşun beyazı ya da vermilyonun yan yana kullanıldığı eski el yazmalarında kurşun beyazının kararmasının kimyasal sebebi nedir?', 'Havadaki hidrojen sülfür gazı veya kükürtlü pigmentlerle tepkimeye giren kurşunun siyah kurşun sülfüre (PbS) dönüşmesi', ['Kurşun beyazının kağıttaki selüloz liflerini yakarak yüzeyde ince bir füzen tabakası oluşturması', 'Su bazlı bağlayıcı olan Arap zamkının kurşun kristallerini çözüp maviye boyaması', 'Ortam sıcaklığı düştüğünde kurşun atomlarının hacimce genleşerek ışığı tamamen soğurması'], 'Yağlı boyada yağ filmi kurşunu korurken, su bazlı tekniklerde açıkta kalan bazik kurşun karbonat kükürtlü bileşiklerle hızla siyah galen (PbS) oluşturur.'),
  ('Kuru pastel ile çalışan bir sanatçının pürüzsüz kuşe kağıt yerine dokulu (dişli/grenli) kağıt veya zımpara yüzeyli karton seçmesinin temel nedeni nedir?', 'Bağlayıcısı çok az olan toz pigment taneciklerinin kağıt yüzeyindeki mikroskobik girintilere mekanik olarak tutunabilmesi', ['Pürüzsüz kağıtların içindeki asidin kuru pasteldeki toprak pigmentlerini anında soldurması', 'Dokulu kağıtların fiksatif püskürtüldüğünde küçülerek renklerin doygunluğunu iki katına çıkarması', 'Tebeşir bazlı çubukların düz yüzeylere temas ettiğinde sürtünme ısısıyla eriyip topaklanması'], 'Kuru pastelde boyayı yüzeye yapıştıracak güçlü bir reçine veya yağ olmadığından, pigmenti tutan asıl unsur kağıdın lifli ve dişli dokusudur.'),
  ('Yağlı pastel çalışmalarının uzun vadeli korunmasında tuval veya kağıt yüzeyin önceden astarlanmasının (gesso sürülmesinin) önerilme sebebi nedir?', 'Pasteldeki kurumayan yağ ve serbest yağ asitlerinin zamanla ham kağıt liflerine sızarak sararma ve kırılganlık yapmasını önlemek', ['Yağlı pastel çubuklarının ham selüloz yüzeyinde hiç iz bırakmadan kayıp gitmesini engellemek', 'Astar içindeki kirecin yağlı pasteli kurutarak birkaç gün içinde taş gibi sertleşmesini sağlamak', 'Üzerine sıkılacak yoğun fiksatifin kağıdın arka yüzüne geçip şasiyi çürütmesini durdurmak'], 'Yağlı pasteldeki mineral yağlar zamanla ham kağıda göç ederek (yağ halesi) asidik bozulmaya yol açabileceğinden bariyer astar kullanımı koruyucudur.'),
  ('Seramik fırınında pişirilecek (terrakota yapılacak) bir kil modelaj heykelinin kurutulmadan önce içinin oyularak et kalınlığının eşitlenmesinin nedeni nedir?', 'Kalın kütlelerin içinde hapsolan nemin ve hava kabarcıklarının fırın ısısıyla genleşip heykeli patlatmasını engellemek', ['Fırınlama sonrasında heykelin içine kolayca erimiş bronz akıtılmasını sağlamak', 'Kil yüzeyine sürülecek fiksatifin gözeneklerden içeriye eşit oranda emilmesini kolaylaştırmak', 'Pişirim sırasında kilin doğal renginin aşı boyası kırmızısından Prusya mavisine dönmesini önlemek'], 'İçi dolu kalın kil heykellerde dış yüzey kururken iç kısım ıslak kalır; fırında yüksek ısıda buharlaşan su çıkacak yer bulamayınca eseri parçalar.'),
  ('Kayıp mum tekniğinde orijinal kil modelden esnek silikon veya jelatin kalıp alınarak mum kopyanın bu kalıp içinde üretilmesinin ("dolaylı yöntem") en büyük avantajı nedir?', 'Döküm sırasında bir kaza yaşansa bile ana kalıp korunduğu için orijinal model kaybolmadan birden fazla bronz edisyon üretilebilmesi', ['Erimiş bronzun silikon kalıbın içine mum aşamasına hiç gerek kalmadan doğrudan dökülebilmesine olanak tanıması', 'Bronz heykelin soğuduktan sonra hiçbir tesviye, kaynak ve patina işlemine ihtiyaç duymadan kalıptan pürüzsüz çıkması', 'Maça kullanımını tamamen ortadan kaldırarak büyük anıtların tek parça dolu metal olarak dökülmesini sağlaması'], 'Doğrudan yöntemde tek mum model eriyip yok olurken, dolaylı yöntemde ana kalıptan içi boş istenen sayıda mum model ve bronz nüsha çoğaltılabilir.'),
  ('Bronz bir heykele yapay patina uygulanmadan önce metal yüzeyin yağ çözücülerle ve kumlamayla titizlikle temizlenmesinin nedeni nedir?', 'Parmak izi ve kalıp ayırıcı yağ kalıntılarının asitli patina çözeltisinin metalle homojen tepkimeye girmesini engellemesi', ['Yüzeydeki yağların nitrik asitle birleştiğinde bronzu eritecek kadar yüksek bir ısı açığa çıkarması', 'Temizlenmeyen bronzun açık havada beklediğinde kendiliğinden kurşun beyazı rengine dönüşmesi', 'Kumlama işleminin metal gözeneklerini kapatarak patina sıvısının yüzeyden tamamen akıp gitmesini sağlaması'], 'Kimyasal patinasyonda potasyum sülfür veya bakır nitrat gibi çözeltilerin lekesiz ve kontrollü renk vermesi için çıplak metal yüzeyde hiçbir yağ bariyeri kalmamalıdır.'),
  ('Restorasyon atölyesinde incelenen 17. yüzyıl tarihli olduğu iddia edilen bir yağlı boya tablonun orijinal mavi katmanında Prusya mavisi tespit edilirse uzman nasıl bir sonuca varır?', 'Prusya mavisi 18. yüzyıl başında sentezlendiği için tablo ya daha geç bir tarihte yapılmıştır ya da sonradan onarım görmüştür', ['Prusya mavisi yalnızca sulu boyada kullanılabildiği için laboratuvar analizinde örnekler birbirine karışmıştır', 'Bu pigment Rönesans\'tan beri bilindiği için bulgu tablonun 17. yüzyıla ait olduğunu kesin biçimde kanıtlar', 'Tablodaki mavi katman aslında zamanla oksitlenerek maviye dönüşmüş bir sarı aşı boyası tabakasıdır'], 'Tarihlendirmede (anakronizm testi) 1704-1706 civarında keşfedilen Prusya mavisinin 17. yüzyıl orijinal katmanında bulunması eserin daha geç üretildiğini gösterir.'),
  ('Füzenle yaptığı büyük boyutlu desende en karanlık gölgeleri söğüt kömürüyle yeterince koyulaştıramayan ve kağıt yüzeyinin parladığını gören bir öğrenci ne yapmalıdır?', 'Gölgelerde kil bağlayıcılı sıkıştırılmış füzen veya siyah kuru pastel kullanarak kağıdın doygunluk sınırını aşmalıdır', ['Söğüt füzenini bezir yağına batırıp kağıda bastırarak çizgileri çini mürekkebine dönüştürmelidir', 'Desenin tamamına kalın bir katman kurşun beyazı astar sürüp üzerine tekrar söğüt füzeniyle gitmelidir', 'Kağıdı zımparalayarak incelttikten sonra füzen tozlarını sıcak suyla yüzeye yapıştırmalıdır'], 'Söğüt füzeni bir noktadan sonra üst üste binmez ve grileşir; derin kadifemsi siyahlar için sıkıştırılmış (komprese) füzen veya füzen kalemi tercih edilir.'),
  ('Kuru pastel ve yağlı pasteli aynı kağıt üzerinde karma teknikle kullanmak isteyen bir sanatçı katman sırasını nasıl planlamalıdır?', 'Önce alt katmanda kuru pastel ve gerekirse hafif fiksatif kullanmalı, yağlı pasteli ise en üst katmanda uygulamalıdır', ['Önce tüm yüzeyi kalın yağlı pastelle kaplamalı, ardından üzerine kuru pastel tozlarını serpiştirerek bitirmelidir', 'İki malzemeyi terebentin içinde eritip tek bir sulu boya karışımı haline getirerek fırçayla sürmelidir', 'Yağlı pasteli kağıda sürdükten sonra ütüyle eritmeli ve sıcak mumun üzerine söğüt füzeniyle kontur çekmelidir'], 'Yağlı üzerine yağsız/kuru malzeme tutunmaz ("fat over lean" ilkesine benzer şekilde); kaygan ve mumlu yağlı pastelin üzerine kuru pastel sürülemez.'),
  ('Açık havada yer alacak bronz büstünde klasik antik eserlerdeki gibi zümrüt yeşili ve turkuaz tonlarında yapay bir patina elde etmek isteyen heykeltıraş hangi kimyasal grubu kullanmalıdır?', 'Isıtılmış bronz yüzeyine bakır nitrat veya amonyum klorür bazlı çözeltiler uygulayarak yeşil bakır tuzları oluşturmalıdır', ['Heykel yüzeyini soğuk bezir yağı ve is karası ile ovarak metalin oksijenle temasını kesmelidir', 'Bronz büstü potasyum sülfür (kükürt karası) çözeltisine daldırarak açık sarıya döndürmelidir', 'Yüzeye yoğun hidroklorik asit döküp ardından kireç kaymağı ile nötralize ederek parlak gümüş rengi vermelidir'], 'Bakır nitrat zümrüt/mavi-yeşil tonlar, amonyum klorür mavi-yeşil küf yeşili verirken; potasyum sülfür (liver of sulfur) kahverengi ve siyah tonlar üretir.'),
  ('Mermer bir bloktan insan figürü yontacak olan heykeltıraş, taş kesme aşamalarında aletlerini kabadan inceye doğru hangi sırayla kullanmalıdır?', 'Sivri uçlu murç (haşlama kalemi) - dişli kalem (gradina) - düz keski - törpü ve aşındırıcı zımparalar', ['Törpü ve zımparalar - düz keski - dişli kalem - sivri uçlu murç', 'Düz keski - sivri uçlu murç - kumlama makinesi - dişli kalem', 'Ebeşuar çubuğu - modelaj teli - dişli kalem - sivri uçlu murç'], 'Geleneksel taş yontmada önce murç ile büyük kütleler kırılır, dişli kalemle form yaklaştırılır, düz kalemle diş izleri silinir ve aşındırıcılarla yüzey parlatılır.'),
  ('Çini mürekkebi ve divit ucuyla çalıştığı tarama (hatching) deseninde ton değerlerini mürekkebi suyla inceltmeden (griye çevirmeden) vermek isteyen bir çizer nasıl hareket etmelidir?', 'Çizgi sıklığını, çapraz tarama katmanlarını ve uç üzerindeki baskıyla değişen çizgi kalınlığını ayarlayarak optik griler üretmelidir', ['Mürekkep şişesinin içine farklı oranlarda kurşun beyazı ekleyerek beş ayrı gri şişe hazırlamalıdır', 'Mürekkep henüz ıslakken üzerine kurutma kağıdı ve hamur silgi bastırarak siyahlığı açmalıdır', 'Divit ucunu önce fiksatife sonra mürekkebe batırarak kağıt üzerinde noktasal dağılmalar yaratmalıdır'], 'Saf siyah çini mürekkebiyle yapılan grafik taramalarda (gravür estetiğinde) açık-koyu ton geçişleri beyaz kağıt boşluğu ile siyah çizgi yoğunluğu arasındaki orandan doğar.'),
  ('Lapis lazuli (doğal ultramarin) ile Fransız ultramarini mikroskop altında karşılaştırıldığında bir sanat tarihçisinin doğal olanı ayırt etmesini sağlayan en belirgin fiziksel kanıt nedir?', 'Doğal ultramarinde elenmiş olsa bile düzensiz boyutta köşeli lazurit kırıkları yanında kalsit ve pirit izlerinin görülmesi, sentetik olanın ise homojen ve yuvarlak tanecikli olması', ['Doğal pigmentin hidroklorik asit damlatıldığında hiç etkilenmemesi, Fransız ultramarininin ise anında parlaması', 'Fransız ultramarininin demir içermesi nedeniyle mıknatıs yaklaştırıldığında tuval üzerinden hareket etmesi', 'Doğal lapis lazuli taneciklerinin ultraviyole ışık altında parlak vermilyon kırmızısı floresans yayması'], 'Öğütülerek elde edilen doğal mineral keskin kenarlı, farklı irilikte kristaller ve safsızlıklar barındırırken; fırında sentezlenen yapay ultramarin çok ince ve tekdüze yuvarlak partiküllüdür.'),
  ('Kiliselerdeki mum dumanına ve sülfürlü şehir havasına yüzyıllarca maruz kalmış bir duvar resminde aşı boyası kırmızısı hiç değişmezken kurşun beyazı ışıklı alanların siyaha dönmesi nasıl açıklanır?', 'Demir oksit doğada en kararlı oksit formundayken, bazik kurşun karbonatın kükürtlü gazlarla tepkimeye girip siyah kurşun sülfür oluşturmasıyla', ['Kırmızı aşı boyasının havadaki isi iten manyetik bir alan yaratması, kurşun beyazının ise is taneciklerini elektrostatik olarak çekmesiyle', 'Mum dumanındaki ısının kurşun beyazını eritip duvarın altındaki siyah füzen astarı yüzeye sızdırmasıyla', 'Kurşun beyazının karanlık ortamda fotosentez benzeri bir süreçle karbon atomlarına ayrışmasıyla'], 'Kimyasal kararlılık farkı nedeniyle hematit (kırmızı okr) sülfürden etkilenmez; ancak kurşun tuzları H2S gazına karşı çok duyarlıdır ve kararır.'),
  ('Füzen, sangin ve çini mürekkebinin kağıtla kurdukları fiziksel ilişki karşılaştırıldığında silinebilirlik açısından ortaya çıkan farkın temel nedeni nedir?', 'Füzen bağlayıcısız iri karbon tozlarıyla yüzeyde tutunurken, sanginin killi yapısının liflere daha çok girmesi ve çini mürekkebinin sıvı reçineyle liflere nüfuz edip kuruması', ['Füzenin içinde silgiyi çeken bitkisel yağlar bulunması, çini mürekkebinin ise kurşun içerdiği için kağıdı delmesi', 'Sanginin ısıtılmış mermer tozundan yapılması, füzenin ise suda çözünen zamk kristallerinden oluşması', 'Çini mürekkebinin yalnızca parşömen üzerinde kullanılması ve selüloz kağıtlarla kimyasal bağ kurmaması'], 'Malzemenin partikül boyutu ve bağlayıcı varlığı kalıcılığı belirler: kuru ve bağlayıcısız füzen yüzeyseldir, kil içeren sangin yarı kalıcıdır, sıvı şellaklı mürekkep ise geri dönüşsüzdür.'),
  ('Kayıp mum bronz döküm ile mermer yontma teknikleri heykelin uzamdaki kompozisyon özgürlüğü (örneğin havada uzanan ince kollar, tek ayak üzerinde duran figürler) açısından karşılaştırıldığında neden bronz daha avantajlıdır?', 'Bronzun yüksek çekme dayanımı ve içi boş hafif yapısı desteksiz uzantılara izin verirken, kırılgan mermerin kendi ağırlığı altında kırılmaması için kütlesel desteklere (ağaç kütüğü vb.) muhtaç olması', ['Mermerin yalnızca dikey yönde kesilebilen lifli bir taş olması, bronzun ise dökümden sonra elle bükülerek şekillendirilebilmesi', 'Bronz heykellerin içine yerleştirilen çelik armatürün dökümden sonra da eseri taşıması, mermerde ise armatür kullanılamaması', 'Kayıp mum tekniğinde yerçekimi etkisinin kalıp içindeki vakum sayesinde tamamen ortadan kalkması'], 'Antik Yunan bronzlarının Roma mermer kopyalarında figürlerin bacak yanlarına ağaç gövdesi veya destek eklenmesinin nedeni, taşın çekme gerilimine dayanamayıp kırılmasıdır.'),
  ('Prusya mavisinin sulu boya veya ince yağlı boya katmanlarında güçlü ışığa maruz kaldığında solması, ancak karanlık bir odaya alındığında rengini kısmen geri kazanması hangi olguyla ilgilidir?', 'Işık etkisiyle ferrik iyonların ferro durumuna indirgenmesi ve karanlıkta havadaki oksijenle yeniden yükseltgenerek mavi rengine dönmesi', ['Pigmentin içindeki su moleküllerinin gündüz buharlaşıp gece ortamdaki nemi sünger gibi geri çekmesi', 'Bağlayıcı olarak kullanılan Arap zamkının ışıkta kristalleşip karanlıkta tekrar sıvılaşarak ışığı kırması', 'Prusya mavisinin içindeki lapis lazuli kalıntılarının sıcaklık farkına bağlı olarak genleşip büzülmesi'], 'Prusya mavisi fotokromik tersinir bir davranış sergiler: UV/görünür ışıkta indirgenerek beyazımsı Berlin beyazına doğru açılır, karanlıkta oksijenle tekrar mavi ferri-ferrosiyanüre döner.'),
  ('Kuru pastel ile yağlı boya tabloların zaman içindeki optik değişimleri karşılaştırıldığında, kuru pastelin yüzyıllar sonra bile ilk günkü tazeliğini korumasının temel sebebi nedir?', 'Yağlı boyadaki kuruyan yağlar zamanla oksitlenip sarararak kırılma indisini değiştirirken, kuru pastelde sararacak bir yağ veya vernik filminin bulunmaması', ['Kuru pastel çubuklarında yalnızca sentetik ve solmayan modern pigmentlerin kullanılabilmesi', 'Pastel kağıtlarının havadaki oksijeni emerek pigmentlerin çevresinde doğal bir vakum alanı yaratması', 'Yağlı boya fırçalarının kıllarından boyaya karışan organik maddelerin renkleri hızla çürütmesi'], 'Edgar Degas ve Rosalba Carriera gibi ustaların pastellerinin hala çok canlı durması, pigmenti çevreleyen ve zamanla kehribarlaşıp koyulaşan bezir yağı/vernik katmanının olmamasındandır.'),
];
